generate_file_no().definition:
CREATE OR REPLACE FUNCTION public.generate_file_no()
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  current_year text;
  next_number int;
  new_file_no text;
begin
  if auth.uid() is null or public.can_create_case() is distinct from true then
    raise exception 'CASE_CREATE_PERMISSION_DENIED' using errcode = '42501';
  end if;
  current_year := extract(year from now())::text;
  loop
    update public.file_no_counters
    set last_number = last_number + 1
    where year = current_year
    returning last_number into next_number;
    if found then
      exit;
    end if;
    begin
      insert into public.file_no_counters(year, last_number)
      values (current_year, 1)
      returning last_number into next_number;
      exit;
    exception when unique_violation then
    end;
  end loop;
  new_file_no :=
    'VP-' || current_year || '-' || lpad(next_number::text, 3, '0');
  return new_file_no;
end;
$function$

case104_flow_guard().definition:
CREATE OR REPLACE FUNCTION public.case104_flow_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
BEGIN
 IF TG_OP='INSERT' AND NEW.track_key='main' AND NEW.template_id<>'civil_ordinary_defendant_v1'
 AND EXISTS(SELECT 1 FROM public.case_defendant_representations WHERE case_id=NEW.case_id) THEN RAISE EXCEPTION 'CASE104_CONTEXT_CONFLICT'; END IF;
 IF TG_OP='UPDATE' AND (OLD.template_id='civil_ordinary_defendant_v1' OR NEW.template_id='civil_ordinary_defendant_v1')
 AND ROW(OLD.case_id,OLD.template_id,OLD.track_key,OLD.started_stage,OLD.start_kind,OLD.started_at,OLD.started_by)
 IS DISTINCT FROM ROW(NEW.case_id,NEW.template_id,NEW.track_key,NEW.started_stage,NEW.start_kind,NEW.started_at,NEW.started_by)
 THEN RAISE EXCEPTION 'CASE104_FLOW_IDENTITY_IMMUTABLE'; END IF;
 IF NEW.template_id='civil_ordinary_defendant_v1' THEN
  IF NEW.track_key<>'main' THEN RAISE EXCEPTION 'CASE104_MAIN_ONLY'; END IF;
  IF NEW.current_stage='D-CIV-03' AND (TG_OP='INSERT' OR OLD.current_stage IS DISTINCT FROM NEW.current_stage)
   AND NOT public.case104_all_resolved(NEW.case_id) THEN RAISE EXCEPTION 'CASE104_UNRESOLVED'; END IF;
 END IF;
 RETURN NEW;
END $function$

case104_deadline_guard().definition:
CREATE OR REPLACE FUNCTION public.case104_deadline_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE did uuid; old_did uuid; BEGIN
 IF TG_TABLE_NAME='case_deadlines' THEN
  did:=CASE WHEN TG_OP='DELETE' THEN OLD.id ELSE NEW.id END;
  IF TG_OP='UPDATE' THEN old_did:=OLD.id; END IF;
 ELSE
  did:=CASE WHEN TG_OP='DELETE' THEN OLD.deadline_id ELSE NEW.deadline_id END;
  IF TG_OP='UPDATE' THEN
   old_did:=OLD.deadline_id;
   IF OLD.deadline_id<>NEW.deadline_id AND EXISTS(SELECT 1 FROM public.case_extension_group_parties WHERE extension_id=OLD.id)
   THEN RAISE EXCEPTION 'CASE104_EXTENSION_IDENTITY_IMMUTABLE'; END IF;
  END IF;
 END IF;
 IF current_user<>'postgres' AND EXISTS(SELECT 1 FROM public.case_service_controls c JOIN public.case_defendant_representations r USING(case_id,party_id) WHERE c.answer_deadline_id IN(did,old_did))
 THEN RAISE EXCEPTION 'CASE104_CONTROLLED_DEADLINE_ONLY'; END IF;
 IF TG_OP='DELETE' THEN RETURN OLD; END IF; RETURN NEW;
END $function$

case097_soft_delete_guard().definition:
CREATE OR REPLACE FUNCTION public.case097_soft_delete_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE changed boolean;
BEGIN
  IF TG_OP = 'INSERT' THEN
    changed := NEW.deleted_at IS NOT NULL OR NEW.deleted_by IS NOT NULL;
  ELSE
    changed := NEW.deleted_at IS DISTINCT FROM OLD.deleted_at
      OR NEW.deleted_by IS DISTINCT FROM OLD.deleted_by;
  END IF;
  IF changed AND NOT EXISTS (SELECT 1 FROM public.user_profiles p
      WHERE p.id = auth.uid() AND p.active IS TRUE AND p.must_change_password IS FALSE
        AND p.role IN ('admin','partner')) THEN
    RAISE EXCEPTION 'CASE_SOFT_DELETE_PARTNER_ADMIN_REQUIRED' USING ERRCODE = '42501';
  END IF;
  RETURN NEW;
END;
$function$

create_case_with_number(uuid).definition:
CREATE OR REPLACE FUNCTION public.create_case_with_number(p_client_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  selected_client_name text := '';
  created_case public.cases%rowtype;
begin
  -- SECURITY DEFINER bypasses RLS, so explicitly authorize before any mutation.
  if auth.uid() is null or public.can_create_case() is distinct from true then
    raise exception 'CASE_CREATE_PERMISSION_DENIED' using errcode = '42501';
  end if;
  if p_client_id is not null then
    select coalesce(c.name, '') into selected_client_name
    from public.clients c where c.id = p_client_id;
    if not found then
      raise exception 'CASE_CLIENT_NOT_FOUND' using errcode = '23503';
    end if;
  end if;
  -- Same initial fields/defaults as the existing Case create handler.
  insert into public.cases (
    file_no, client_id, title, client_name, court_name, case_number,
    phase, status, owner_name, physical_storage_type, physical_storage_detail,
    created_at, updated_at
  ) values (
    public.generate_file_no(), p_client_id, '', selected_client_name, '', '',
    'litigation', 'Active', '', 'Cabinet', '', now(), now()
  ) returning * into created_case;
  return jsonb_build_object('id', created_case.id, 'file_no', created_case.file_no);
end;
$function$

case104_sync(bigint,uuid[],jsonb).definition:
CREATE OR REPLACE FUNCTION public.case104_sync(p_case_id bigint, p_parties uuid[], p_versions jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE pid uuid; c public.case_service_controls; d public.case_deadlines; day date; old_d jsonb; effects jsonb:='[]'; BEGIN
 FOR pid IN SELECT DISTINCT x FROM unnest(p_parties) x ORDER BY x LOOP
  day:=public.case104_filed_date(p_case_id,pid);
  SELECT * INTO c FROM public.case_service_controls WHERE case_id=p_case_id AND party_id=pid FOR UPDATE;
  IF c.party_id IS NULL THEN
   INSERT INTO public.case_service_controls(party_id,case_id,answer_filed_on,updated_by) VALUES(pid,p_case_id,day,auth.uid());
   CONTINUE;
  END IF;
  IF c.answer_deadline_id IS NOT NULL THEN
   d:=public.case104_deadline_token(c.answer_deadline_id,p_versions);old_d:=to_jsonb(d);
   IF d.case_id<>p_case_id THEN RAISE EXCEPTION 'CASE104_DEADLINE_UNAVAILABLE'; END IF;
   IF day IS NOT NULL AND c.answer_filed_on IS NULL THEN
    IF d.status<>'Active' THEN RAISE EXCEPTION 'CASE104_DEADLINE_REVIEW_REQUIRED'; END IF;
    UPDATE public.case_deadlines SET status='Done',updated_at=clock_timestamp() WHERE id=d.id RETURNING * INTO d;
   ELSIF day IS NULL AND c.answer_filed_on IS NOT NULL THEN
    -- Reopen only the completion performed by this contract, never a later independent edit/cancellation.
    IF d.status<>'Done' OR NOT EXISTS(SELECT 1 FROM public.case_service_events e CROSS JOIN LATERAL jsonb_array_elements(coalesce(e.after_data->'deadline_effects','[]')) x
     WHERE e.case_id=p_case_id AND e.action LIKE 'case104_%' AND x->'after'->>'id'=d.id::text AND x->'before'->>'status'='Active' AND x->'after'->>'status'='Done'
     AND (x->'after'->>'updated_at')::timestamptz IS NOT DISTINCT FROM d.updated_at)
    THEN RAISE EXCEPTION 'CASE104_DEADLINE_REVIEW_REQUIRED'; END IF;
    UPDATE public.case_deadlines SET status='Active',updated_at=clock_timestamp() WHERE id=d.id RETURNING * INTO d;
   END IF;
   IF old_d IS DISTINCT FROM to_jsonb(d) THEN effects:=effects||jsonb_build_array(jsonb_build_object('party_id',pid,'before',old_d,'after',to_jsonb(d))); END IF;
  END IF;
  IF c.answer_filed_on IS DISTINCT FROM day THEN
   UPDATE public.case_service_controls SET answer_filed_on=day,version=version+1,updated_by=auth.uid(),updated_at=clock_timestamp() WHERE party_id=pid;
  END IF;
 END LOOP;
 RETURN effects;
END $function$

case104_deadline_token(uuid,jsonb).definition:
CREATE OR REPLACE FUNCTION public.case104_deadline_token(p_deadline_id uuid, p_versions jsonb)
 RETURNS case_deadlines
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE d public.case_deadlines; t jsonb; BEGIN
 SELECT * INTO d FROM public.case_deadlines WHERE id=p_deadline_id FOR UPDATE;
 t:=p_versions->'deadlines'->p_deadline_id::text;
 IF d.id IS NULL OR d.deleted_at IS NOT NULL OR d.status NOT IN('Active','Done') THEN RAISE EXCEPTION 'CASE104_DEADLINE_UNAVAILABLE'; END IF;
 IF jsonb_typeof(t) IS DISTINCT FROM 'object' OR (t->>'updated_at')::timestamptz IS DISTINCT FROM d.updated_at OR (t->>'due')::date IS DISTINCT FROM d.current_due_date
 THEN RAISE EXCEPTION 'CASE104_STALE_DEADLINE'; END IF;
 RETURN d;
END $function$

case098_save(bigint,integer,text,jsonb).definition:
CREATE OR REPLACE FUNCTION public.case098_save(p_case_id bigint, p_version integer, p_section text, p_data jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE c public.case_work_core; old_facts jsonb; new_facts jsonb; person uuid; entry jsonb; target uuid; actor public.user_profiles;
BEGIN
 IF NOT public.case097_session_ready() OR NOT public.can_view_case_data()
 OR (p_section IN ('team','work') AND NOT public.case097_process_writer())
 OR (p_section='next' AND NOT public.can_write_case_data()) THEN RAISE EXCEPTION 'CASE098_FORBIDDEN' USING ERRCODE='42501'; END IF;
 IF p_section IS NULL OR p_section NOT IN ('team','work','next') OR p_version IS NULL OR p_version<0
 OR p_data IS NULL OR jsonb_typeof(p_data)<>'object' THEN RAISE EXCEPTION 'CASE098_INVALID_INPUT'; END IF;
 PERFORM 1 FROM public.cases WHERE id=p_case_id FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'CASE098_NOT_FOUND'; END IF;
 SELECT * INTO c FROM public.case_work_core WHERE case_id=p_case_id;
 IF coalesce(c.version,0)<>p_version THEN RAISE EXCEPTION 'CASE098_STALE'; END IF;
 SELECT jsonb_build_object('core',to_jsonb(c),'team',(SELECT coalesce(jsonb_agg(to_jsonb(t) ORDER BY team_role,person_id),'[]') FROM public.case_team_assignments t WHERE case_id=p_case_id)) INTO old_facts;
 IF c.case_id IS NULL THEN
  INSERT INTO public.case_work_core(case_id,updated_by) VALUES(p_case_id,auth.uid()) RETURNING * INTO c;
 END IF;
 IF p_section='team' THEN
  IF EXISTS(SELECT 1 FROM jsonb_object_keys(p_data) k WHERE k<>'assignments') OR jsonb_typeof(p_data->'assignments') IS DISTINCT FROM 'array'
   OR jsonb_array_length(p_data->'assignments')>100 THEN RAISE EXCEPTION 'CASE098_INVALID_INPUT'; END IF;
  FOR entry IN SELECT value FROM jsonb_array_elements(p_data->'assignments') LOOP
   IF jsonb_typeof(entry)<>'object' OR EXISTS(SELECT 1 FROM jsonb_object_keys(entry) k WHERE k NOT IN('person_id','team_role'))
    OR entry->>'team_role' IS NULL OR entry->>'team_role' NOT IN('lead','strategy','qc','member','current_actor') THEN RAISE EXCEPTION 'CASE098_INVALID_INPUT'; END IF;
   person:=(entry->>'person_id')::uuid;
   IF person IS NULL OR (NOT EXISTS(SELECT 1 FROM public.case_team_assignments t WHERE t.case_id=p_case_id AND t.person_id=person AND t.team_role=entry->>'team_role')
    AND NOT EXISTS(SELECT 1 FROM public.user_profiles p WHERE p.id=person AND p.active IS TRUE AND p.account_type='operational' AND p.assignable IS TRUE)) THEN RAISE EXCEPTION 'CASE098_PERSON_INELIGIBLE'; END IF;
  END LOOP;
  DELETE FROM public.case_team_assignments WHERE case_id=p_case_id;
  INSERT INTO public.case_team_assignments(case_id,person_id,team_role) SELECT p_case_id,(value->>'person_id')::uuid,value->>'team_role' FROM jsonb_array_elements(p_data->'assignments');
 ELSIF p_section='work' THEN
  IF EXISTS(SELECT 1 FROM jsonb_object_keys(p_data) k WHERE k<>'work_state') OR NOT(p_data ? 'work_state') THEN RAISE EXCEPTION 'CASE098_INVALID_INPUT'; END IF;
  UPDATE public.case_work_core SET work_state=p_data->>'work_state' WHERE case_id=p_case_id;
 ELSE
  IF EXISTS(SELECT 1 FROM jsonb_object_keys(p_data) k WHERE k NOT IN('mode','task_id','title','assignee_id','due'))
   OR p_data->>'mode' IS NULL OR p_data->>'mode' NOT IN('none','manual','task') THEN RAISE EXCEPTION 'CASE098_INVALID_INPUT'; END IF;
  IF p_data->>'mode'='task' THEN
   target:=(p_data->>'task_id')::uuid;
   -- Lock the existing task for validation, but never edit or copy its business facts.
   PERFORM 1 FROM public.case_tasks WHERE id=target AND case_id=p_case_id AND deleted_at IS NULL AND coalesce(status,'Pending')<>'Done' FOR SHARE;
   IF NOT FOUND THEN RAISE EXCEPTION 'CASE098_TASK_UNAVAILABLE'; END IF;
  ELSIF p_data->>'mode'='manual' THEN
   person:=nullif(p_data->>'assignee_id','')::uuid;
   IF person IS NOT NULL AND person IS DISTINCT FROM c.next_assignee_id AND NOT EXISTS(SELECT 1 FROM public.user_profiles p WHERE p.id=person AND p.active IS TRUE AND p.account_type='operational' AND p.assignable IS TRUE) THEN RAISE EXCEPTION 'CASE098_PERSON_INELIGIBLE'; END IF;
   IF nullif(btrim(p_data->>'title'),'') IS NULL THEN RAISE EXCEPTION 'CASE098_INVALID_INPUT'; END IF;
  END IF;
  UPDATE public.case_work_core SET next_mode=p_data->>'mode',next_task_id=target,
   next_title=CASE WHEN p_data->>'mode'='manual' THEN btrim(p_data->>'title') END,
   next_assignee_id=person,next_due=CASE WHEN p_data->>'mode'='manual' THEN nullif(p_data->>'due','')::date END WHERE case_id=p_case_id;
 END IF;
 UPDATE public.case_work_core SET version=p_version+1,updated_at=clock_timestamp(),updated_by=auth.uid() WHERE case_id=p_case_id RETURNING * INTO c;
 SELECT jsonb_build_object('core',to_jsonb(c),'team',(SELECT coalesce(jsonb_agg(to_jsonb(t) ORDER BY team_role,person_id),'[]') FROM public.case_team_assignments t WHERE case_id=p_case_id)) INTO new_facts;
 SELECT * INTO actor FROM public.user_profiles WHERE id=auth.uid();
 INSERT INTO public.case_audit_logs(case_id,table_name,record_id,action,user_id,user_name,user_role,old_data,new_data,note)
 VALUES(p_case_id,'case_work_core',p_case_id::text,'update',auth.uid(),coalesce(nullif(actor.staff_name,''),actor.full_name),actor.role,old_facts,new_facts,'case098_'||p_section);
 RETURN public.case098_read(p_case_id);
EXCEPTION WHEN invalid_text_representation OR invalid_datetime_format OR datetime_field_overflow OR check_violation OR unique_violation OR not_null_violation THEN RAISE EXCEPTION 'CASE098_INVALID_INPUT';
END $function$

case104_parties(bigint,jsonb,text,boolea.definition:
CREATE OR REPLACE FUNCTION public.case104_parties(p_case_id bigint, p_ids jsonb, p_role text, p_represented boolean DEFAULT true)
 RETURNS uuid[]
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE ids uuid[]; n integer; BEGIN
 IF jsonb_typeof(p_ids) IS DISTINCT FROM 'array' OR jsonb_array_length(p_ids)<1 OR jsonb_array_length(p_ids)>100 THEN RAISE EXCEPTION 'CASE104_PARTIES_REQUIRED'; END IF;
 SELECT array_agg(x::uuid ORDER BY x::uuid),count(DISTINCT x) INTO ids,n FROM jsonb_array_elements_text(p_ids) x;
 IF n<>cardinality(ids) OR array_position(ids,NULL) IS NOT NULL THEN RAISE EXCEPTION 'CASE104_DUPLICATE_PARTY'; END IF;
 PERFORM 1 FROM public.parties WHERE id=ANY(ids) ORDER BY id FOR SHARE;
 IF (SELECT count(*) FROM public.parties WHERE id=ANY(ids) AND case_id=p_case_id AND role=p_role AND deleted_at IS NULL)<>cardinality(ids)
 OR (p_represented AND (SELECT count(*) FROM public.case_defendant_representations WHERE case_id=p_case_id AND party_id=ANY(ids) AND active)<>cardinality(ids))
 THEN RAISE EXCEPTION 'CASE104_PARTY_UNAVAILABLE'; END IF;
 RETURN ids;
END $function$

case104_save(bigint,uuid,text,jsonb,json.definition:
CREATE OR REPLACE FUNCTION public.case104_save(p_case_id bigint, p_request_id uuid, p_action text, p_versions jsonb, p_data jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE actor public.user_profiles; receipt public.case_service_events; req jsonb; v bigint; old_facts jsonb; new_facts jsonb;
 allowed text[]; ids uuid[]; old_ids uuid[]; affected uuid[]:='{}'; pid uuid; fid uuid; dst uuid; day date; why text; entry jsonb; deps jsonb;
 f public.case_answer_filings; c public.case_service_controls; a public.case_service_attempts; d public.case_deadlines; g public.case_extension_groups;
 x public.case_extension_group_parties; i public.case_flow_instances; prev public.case_flow_transitions; old_d jsonb; effects jsonb:='[]';
 event_id uuid:=gen_random_uuid(); result jsonb; cv integer; code text; before_stage text; state text; existed boolean; impact boolean; claimant uuid;
BEGIN
 IF NOT(public.case097_session_ready() AND public.can_view_case_data() AND public.case097_process_writer()) THEN RAISE EXCEPTION 'CASE104_FORBIDDEN' USING ERRCODE='42501'; END IF;
 SELECT * INTO actor FROM public.user_profiles WHERE id=auth.uid();
 IF p_request_id IS NULL OR jsonb_typeof(p_versions) IS DISTINCT FROM 'object' OR jsonb_typeof(p_data) IS DISTINCT FROM 'object' OR p_action IS NULL
 OR EXISTS(SELECT 1 FROM jsonb_object_keys(p_versions) k WHERE k NOT IN('scope','entity','flow','core','deadlines')) THEN RAISE EXCEPTION 'CASE104_INVALID_INPUT'; END IF;
 allowed:=CASE p_action
 WHEN 'representation' THEN ARRAY['parties','active','reason']
 WHEN 'service' THEN ARRAY['party_id','attempt_id','method','attempted_on','result','failure_kind','failure_reason','note','confirm_lawful']
 WHEN 'service_void' THEN ARRAY['party_id','attempt_id','reason']
 WHEN 'deadline' THEN ARRAY['party_id','existing_id','due','confirmed','reason']
 WHEN 'filing_create' THEN ARRAY['id','parties','filed_on','document_ref','note']
 WHEN 'filing_correct' THEN ARRAY['id','parties','filed_on','document_ref','note','reason','replacement_id','dependencies']
 WHEN 'filing_void' THEN ARRAY['id','reason','dependencies']
 WHEN 'extension' THEN ARRAY['id','parties','requested_on','document_ref','note','grants','confirmed','reason']
 WHEN 'counterclaim_create' THEN ARRAY['id','version','filing_id','filed_on','document_ref','note','claimants','targets']
 WHEN 'counterclaim_correct' THEN ARRAY['id','version','filing_id','filed_on','document_ref','note','claimants','targets','reason','replacement_id']
 WHEN 'counterclaim_void' THEN ARRAY['id','version','reason']
 WHEN 'counterclaim_relink' THEN ARRAY['id','version','filing_id','reason']
 WHEN 'flow_start' THEN ARRAY['id','stage','start_kind','acknowledged','filing_method']
 WHEN 'flow_transition' THEN ARRAY['id','stage','confirmed','reason','corrects_id']
 WHEN 'next' THEN ARRAY['next','assignments'] END;
 IF allowed IS NULL OR EXISTS(SELECT 1 FROM jsonb_object_keys(p_data) k WHERE NOT(k=ANY(allowed))) THEN RAISE EXCEPTION 'CASE104_INVALID_INPUT'; END IF;
 IF p_action NOT IN('service','next','flow_transition') AND actor.role NOT IN('lawyer','partner','admin') THEN RAISE EXCEPTION 'CASE104_LAWYER_REQUIRED' USING ERRCODE='42501'; END IF;
 req:=jsonb_build_object('case_id',p_case_id,'action',p_action,'versions',p_versions,'data',p_data);
 -- Serialize all 104 operations (including counterclaim dependencies), without updating legacy Case rows.
 PERFORM 1 FROM public.cases WHERE id=p_case_id FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'CASE104_NOT_FOUND'; END IF;
 SELECT * INTO receipt FROM public.case_service_events WHERE request_id=p_request_id;
 IF receipt.id IS NOT NULL THEN
  IF receipt.actor_id<>auth.uid() OR receipt.action<>'case104_'||p_action OR receipt.request_data IS DISTINCT FROM req THEN RAISE EXCEPTION 'CASE104_REQUEST_CONFLICT'; END IF;
  RETURN receipt.after_data->'result';
 END IF;
 SELECT count(*) INTO v FROM public.case_service_events WHERE case_id=p_case_id AND action LIKE 'case104_%';
 IF (p_versions->>'scope')::bigint IS DISTINCT FROM v THEN RAISE EXCEPTION 'CASE104_STALE'; END IF;
 IF EXISTS(SELECT 1 FROM public.case_flow_instances WHERE case_id=p_case_id AND track_key='main' AND template_id<>'civil_ordinary_defendant_v1') THEN RAISE EXCEPTION 'CASE104_CONTEXT_CONFLICT'; END IF;
 old_facts:=public.case104_read(p_case_id)-'history'-'transitions'-'stages'-'template';
 why:=nullif(btrim(p_data->>'reason'),'');
 IF length(p_data::text)>150000 THEN RAISE EXCEPTION 'CASE104_INVALID_INPUT'; END IF;

 IF p_action='representation' THEN
  IF jsonb_typeof(p_data->'active') IS DISTINCT FROM 'boolean' THEN RAISE EXCEPTION 'CASE104_INVALID_INPUT'; END IF;
  ids:=public.case104_parties(p_case_id,p_data->'parties','defendant',false);
  IF p_data->'active'='false'::jsonb AND why IS NULL THEN RAISE EXCEPTION 'CASE104_REASON_REQUIRED'; END IF;
  FOR pid IN SELECT unnest(ids) LOOP
   SELECT EXISTS(SELECT 1 FROM public.case_defendant_representations WHERE case_id=p_case_id AND party_id=pid) INTO existed;
   IF NOT existed AND p_data->'active'='false'::jsonb THEN RAISE EXCEPTION 'CASE104_PARTY_UNAVAILABLE'; END IF;
   -- An old unstructured filed date cannot silently become a newly inferred Filing.
   IF NOT existed AND EXISTS(SELECT 1 FROM public.case_service_controls WHERE party_id=pid AND answer_filed_on IS NOT NULL) THEN RAISE EXCEPTION 'CASE104_LEGACY_FILING_REVIEW'; END IF;
   INSERT INTO public.case_defendant_representations(case_id,party_id,active,reason,recorded_by,updated_by)
   VALUES(p_case_id,pid,(p_data->>'active')::boolean,why,auth.uid(),auth.uid())
   ON CONFLICT(case_id,party_id) DO UPDATE SET active=excluded.active,reason=excluded.reason,version=case_defendant_representations.version+1,updated_at=clock_timestamp(),updated_by=auth.uid();
  END LOOP;
  -- Withdrawal/re-add changes membership only; no sync, completion, deletion or fresh obligation.
  affected:=ids;

 ELSIF p_action IN('service','service_void','deadline') THEN
  ids:=public.case104_parties(p_case_id,jsonb_build_array(p_data->>'party_id'),'defendant');pid:=ids[1];affected:=ids;
  SELECT * INTO c FROM public.case_service_controls WHERE party_id=pid AND case_id=p_case_id FOR UPDATE;
  IF c.party_id IS NULL THEN
   INSERT INTO public.case_service_controls(party_id,case_id,answer_filed_on,updated_by) VALUES(pid,p_case_id,public.case104_filed_date(p_case_id,pid),auth.uid()) RETURNING * INTO c;
  END IF;
  IF p_action='service_void' THEN
   IF why IS NULL THEN RAISE EXCEPTION 'CASE104_REASON_REQUIRED'; END IF;
   SELECT * INTO a FROM public.case_service_attempts WHERE id=(p_data->>'attempt_id')::uuid AND party_id=pid AND case_id=p_case_id FOR UPDATE;
   IF a.id IS NULL OR a.result='void' THEN RAISE EXCEPTION 'CASE104_ATTEMPT_UNAVAILABLE'; END IF;
   IF c.lawful_attempt_id=a.id AND (c.answer_deadline_id IS NOT NULL OR c.answer_filed_on IS NOT NULL) THEN RAISE EXCEPTION 'CASE104_DEADLINE_REVIEW_REQUIRED'; END IF;
   UPDATE public.case_service_attempts SET result='void',void_reason=why,updated_at=clock_timestamp(),updated_by=auth.uid() WHERE id=a.id;
   IF c.lawful_attempt_id=a.id THEN UPDATE public.case_service_controls SET lawful_attempt_id=NULL,lawful_at=NULL,lawful_by=NULL WHERE party_id=pid; END IF;
  ELSIF p_action='service' THEN
   day:=(p_data->>'attempted_on')::date;
   IF day IS NOT NULL AND (NOT isfinite(day) OR day>(current_timestamp AT TIME ZONE 'Asia/Bangkok')::date) THEN RAISE EXCEPTION 'CASE104_INVALID_DATE'; END IF;
   IF p_data->>'result' IS NULL OR p_data->>'result' NOT IN('pending','served','failed') THEN RAISE EXCEPTION 'CASE104_INVALID_INPUT'; END IF;
   IF p_data->'confirm_lawful'='true'::jsonb AND (actor.role NOT IN('lawyer','partner','admin') OR p_data->>'result'<>'served') THEN RAISE EXCEPTION 'CASE104_LAWYER_REQUIRED'; END IF;
   IF p_data ? 'confirm_lawful' AND jsonb_typeof(p_data->'confirm_lawful') IS DISTINCT FROM 'boolean' THEN RAISE EXCEPTION 'CASE104_INVALID_INPUT'; END IF;
   dst:=(p_data->>'attempt_id')::uuid;
   IF dst IS NULL THEN
    dst:=gen_random_uuid();
    INSERT INTO public.case_service_attempts(id,party_id,case_id,method,attempted_on,result,failure_kind,failure_reason,note,recorded_by,updated_by)
    VALUES(dst,pid,p_case_id,p_data->>'method',day,p_data->>'result',p_data->>'failure_kind',p_data->>'failure_reason',p_data->>'note',auth.uid(),auth.uid());
   ELSE
    SELECT * INTO a FROM public.case_service_attempts WHERE id=dst AND party_id=pid AND case_id=p_case_id FOR UPDATE;
    IF a.id IS NULL OR a.result<>'pending' THEN RAISE EXCEPTION 'CASE104_ATTEMPT_FINAL'; END IF;
    UPDATE public.case_service_attempts SET method=p_data->>'method',attempted_on=day,result=p_data->>'result',failure_kind=p_data->>'failure_kind',failure_reason=p_data->>'failure_reason',note=p_data->>'note',updated_at=clock_timestamp(),updated_by=auth.uid() WHERE id=dst;
   END IF;
   IF p_data->'confirm_lawful'='true'::jsonb THEN
    IF c.lawful_attempt_id IS NOT NULL AND c.lawful_attempt_id<>dst THEN RAISE EXCEPTION 'CASE104_DEADLINE_REVIEW_REQUIRED'; END IF;
    UPDATE public.case_service_controls SET lawful_attempt_id=dst,lawful_at=clock_timestamp(),lawful_by=auth.uid() WHERE party_id=pid;
   END IF;
  ELSE
   IF p_data->'confirmed' IS DISTINCT FROM 'true'::jsonb THEN RAISE EXCEPTION 'CASE104_CONFIRM_REQUIRED'; END IF;
   IF c.answer_deadline_id IS NOT NULL OR public.case104_filed_date(p_case_id,pid) IS NOT NULL THEN RAISE EXCEPTION 'CASE104_DEADLINE_LINKED'; END IF;
   dst:=(p_data->>'existing_id')::uuid;
   IF dst IS NULL THEN
    day:=(p_data->>'due')::date;IF day IS NULL OR NOT isfinite(day) THEN RAISE EXCEPTION 'CASE104_INVALID_DATE'; END IF;
    INSERT INTO public.case_deadlines(case_id,order_no,deadline_type,original_due_date,current_due_date,status,note)
    VALUES(p_case_id,(SELECT coalesce(max(order_no),0)+1 FROM public.case_deadlines WHERE case_id=p_case_id),'answer',day,day,'Active',why) RETURNING * INTO d;
   ELSE
    d:=public.case104_deadline_token(dst,p_versions);
    IF d.case_id<>p_case_id OR d.deadline_type<>'answer' OR d.status<>'Active' OR EXISTS(SELECT 1 FROM public.case_service_controls WHERE answer_deadline_id=dst OR default_deadline_id=dst) THEN RAISE EXCEPTION 'CASE104_DEADLINE_UNAVAILABLE'; END IF;
   END IF;
   UPDATE public.case_service_controls SET answer_deadline_id=d.id WHERE party_id=pid;
  END IF;
  UPDATE public.case_service_controls SET version=version+1,updated_at=clock_timestamp(),updated_by=auth.uid() WHERE party_id=pid;

 ELSIF p_action IN('filing_create','filing_correct','filing_void') THEN
  fid:=(p_data->>'id')::uuid;IF fid IS NULL THEN RAISE EXCEPTION 'CASE104_INVALID_INPUT'; END IF;
  SELECT * INTO f FROM public.case_answer_filings WHERE id=fid FOR UPDATE;
  IF p_action='filing_create' THEN
   IF f.id IS NOT NULL OR (p_versions->>'entity')::integer IS DISTINCT FROM 0 THEN RAISE EXCEPTION 'CASE104_STALE'; END IF;
  ELSE
   IF f.id IS NULL OR f.case_id<>p_case_id OR f.lifecycle<>'active' OR (p_versions->>'entity')::integer IS DISTINCT FROM f.version THEN RAISE EXCEPTION 'CASE104_STALE'; END IF;
   IF why IS NULL THEN RAISE EXCEPTION 'CASE104_REASON_REQUIRED'; END IF;
   SELECT array_agg(party_id ORDER BY party_id) INTO old_ids FROM public.case_answer_filing_parties WHERE filing_id=f.id AND coverage_version=f.coverage_version;
  END IF;
  IF p_action='filing_void' THEN ids:=old_ids;
  ELSIF p_action='filing_create' OR p_data ? 'parties' THEN ids:=public.case104_parties(p_case_id,p_data->'parties','defendant');
  ELSE ids:=old_ids; END IF;
  affected:=coalesce(old_ids,'{}'::uuid[])||coalesce(ids,'{}'::uuid[]);
  impact:=p_action='filing_void' OR (p_action='filing_correct' AND (old_ids IS DISTINCT FROM ids OR p_data ? 'replacement_id'));
  deps:=coalesce(p_data->'dependencies','[]'::jsonb);
  IF jsonb_typeof(deps)<>'array' OR jsonb_array_length(deps)>100 OR (NOT impact AND jsonb_array_length(deps)>0) THEN RAISE EXCEPTION 'CASE104_INVALID_INPUT'; END IF;
  IF impact AND EXISTS(SELECT 1 FROM public.case_counterclaims q WHERE q.filing_id=fid AND q.lifecycle='active'
   AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(deps) z WHERE z->>'id'=q.id::text)) THEN RAISE EXCEPTION 'CASE104_ACTIVE_COUNTERCLAIM'; END IF;
  IF (SELECT count(*) FROM jsonb_array_elements(deps))<>(SELECT count(DISTINCT z->>'id') FROM jsonb_array_elements(deps) z) THEN RAISE EXCEPTION 'CASE104_INVALID_INPUT'; END IF;
  -- All dependencies are explicit. A replacement is created inside this same transaction, never exposed partially.
  IF p_action<>'filing_void' THEN
   day:=coalesce((p_data->>'filed_on')::date,f.filed_on);
   IF day IS NULL OR NOT isfinite(day) OR day>(current_timestamp AT TIME ZONE 'Asia/Bangkok')::date THEN RAISE EXCEPTION 'CASE104_INVALID_DATE'; END IF;
   dst:=CASE WHEN p_action='filing_create' THEN fid ELSE coalesce((p_data->>'replacement_id')::uuid,fid) END;
   IF p_action='filing_create' OR dst<>fid THEN
    INSERT INTO public.case_answer_filings(id,case_id,filed_on,document_ref,note,replaces_id,reason,recorded_by,updated_by)
    VALUES(dst,p_case_id,day,CASE WHEN p_data ? 'document_ref' THEN nullif(p_data->>'document_ref','') ELSE f.document_ref END,coalesce(p_data->>'note',f.note),CASE WHEN dst<>fid THEN fid ELSE NULL END,why,auth.uid(),auth.uid());cv:=1;
   ELSE
    cv:=f.coverage_version+CASE WHEN ids IS DISTINCT FROM old_ids THEN 1 ELSE 0 END;
    UPDATE public.case_answer_filings SET filed_on=day,document_ref=CASE WHEN p_data ? 'document_ref' THEN nullif(p_data->>'document_ref','') ELSE document_ref END,note=CASE WHEN p_data ? 'note' THEN p_data->>'note' ELSE note END,
     reason=why,version=version+1,coverage_version=cv,updated_at=clock_timestamp(),updated_by=auth.uid() WHERE id=fid;
   END IF;
   IF p_action='filing_create' OR dst<>fid OR ids IS DISTINCT FROM old_ids THEN INSERT INTO public.case_answer_filing_parties SELECT dst,cv,u.party_id FROM unnest(ids) u(party_id); END IF;
  END IF;
  FOR entry IN SELECT value FROM jsonb_array_elements(deps) LOOP
   IF entry->>'action' IS NULL OR entry->>'action' NOT IN('void','correct','relink') OR NOT EXISTS(SELECT 1 FROM public.case_counterclaims WHERE id=(entry->>'id')::uuid AND case_id=p_case_id AND filing_id=fid AND lifecycle='active') THEN RAISE EXCEPTION 'CASE104_INVALID_DEPENDENCY'; END IF;
   PERFORM public.case104_counterclaim_write(p_case_id,entry->>'action',entry-'action');
  END LOOP;
  IF p_action='filing_void' OR (p_action='filing_correct' AND dst<>fid) THEN
   IF EXISTS(SELECT 1 FROM public.case_counterclaims WHERE filing_id=fid AND lifecycle='active') THEN RAISE EXCEPTION 'CASE104_ACTIVE_COUNTERCLAIM'; END IF;
   UPDATE public.case_answer_filings SET lifecycle=CASE WHEN p_action='filing_void' THEN 'void' ELSE 'corrected' END,reason=why,version=version+1,updated_at=clock_timestamp(),updated_by=auth.uid() WHERE id=fid;
  END IF;
  effects:=public.case104_sync(p_case_id,affected,p_versions);

 ELSIF p_action LIKE 'counterclaim_%' THEN
  dst:=public.case104_counterclaim_write(p_case_id,substr(p_action,14),p_data);

 ELSIF p_action='extension' THEN
  dst:=(p_data->>'id')::uuid;IF dst IS NULL THEN RAISE EXCEPTION 'CASE104_INVALID_INPUT'; END IF;
  SELECT * INTO g FROM public.case_extension_groups WHERE id=dst FOR UPDATE;
  IF g.id IS NULL THEN
   IF (p_versions->>'entity')::integer IS DISTINCT FROM 0 THEN RAISE EXCEPTION 'CASE104_STALE'; END IF;
   ids:=public.case104_parties(p_case_id,p_data->'parties','defendant');
   day:=(p_data->>'requested_on')::date;IF day IS NOT NULL AND (NOT isfinite(day) OR day>(current_timestamp AT TIME ZONE 'Asia/Bangkok')::date) THEN RAISE EXCEPTION 'CASE104_INVALID_DATE'; END IF;
   INSERT INTO public.case_extension_groups(id,case_id,requested_on,document_ref,note,recorded_by,updated_by) VALUES(dst,p_case_id,day,nullif(p_data->>'document_ref',''),p_data->>'note',auth.uid(),auth.uid()) RETURNING * INTO g;
   FOR pid IN SELECT unnest(ids) LOOP
    SELECT * INTO c FROM public.case_service_controls WHERE party_id=pid AND case_id=p_case_id FOR UPDATE;
    IF c.answer_deadline_id IS NULL OR public.case104_filed_date(p_case_id,pid) IS NOT NULL THEN RAISE EXCEPTION 'CASE104_DEADLINE_UNAVAILABLE'; END IF;
    d:=public.case104_deadline_token(c.answer_deadline_id,p_versions);
    IF d.case_id<>p_case_id OR d.status<>'Active' THEN RAISE EXCEPTION 'CASE104_DEADLINE_UNAVAILABLE'; END IF;
    INSERT INTO public.case_extension_group_parties(group_id,party_id,deadline_id) VALUES(dst,pid,d.id);
   END LOOP;
  ELSE
   IF g.case_id<>p_case_id OR (p_versions->>'entity')::integer IS DISTINCT FROM g.version THEN RAISE EXCEPTION 'CASE104_STALE'; END IF;
   IF why IS NULL THEN RAISE EXCEPTION 'CASE104_REASON_REQUIRED'; END IF;
   IF p_data ? 'parties' THEN RAISE EXCEPTION 'CASE104_EXTENSION_COVERAGE_IMMUTABLE'; END IF;
   IF p_data ? 'requested_on' THEN RAISE EXCEPTION 'CASE104_INVALID_INPUT'; END IF;
   SELECT array_agg(party_id ORDER BY party_id) INTO ids FROM public.case_extension_group_parties WHERE group_id=g.id;
   PERFORM public.case104_parties(p_case_id,to_jsonb(ids),'defendant');
  END IF;
  affected:=ids;
  IF p_data ? 'grants' THEN
   IF p_data->'confirmed' IS DISTINCT FROM 'true'::jsonb THEN RAISE EXCEPTION 'CASE104_CONFIRM_REQUIRED'; END IF;
   IF jsonb_typeof(p_data->'grants') IS DISTINCT FROM 'array' OR jsonb_array_length(p_data->'grants')<>cardinality(ids)
    OR (SELECT count(DISTINCT z->>'party_id') FROM jsonb_array_elements(p_data->'grants') z)<>cardinality(ids) THEN RAISE EXCEPTION 'CASE104_EXTENSION_COVERAGE'; END IF;
   FOR entry IN SELECT value FROM jsonb_array_elements(p_data->'grants') ORDER BY value->>'party_id' LOOP
    IF EXISTS(SELECT 1 FROM jsonb_object_keys(entry) k WHERE k NOT IN('party_id','due')) THEN RAISE EXCEPTION 'CASE104_INVALID_INPUT'; END IF;
    pid:=(entry->>'party_id')::uuid;day:=(entry->>'due')::date;
    IF pid IS NULL OR NOT(pid=ANY(ids)) OR day IS NULL OR NOT isfinite(day) OR public.case104_filed_date(p_case_id,pid) IS NOT NULL THEN RAISE EXCEPTION 'CASE104_EXTENSION_COVERAGE'; END IF;
    SELECT * INTO x FROM public.case_extension_group_parties WHERE group_id=dst AND party_id=pid FOR UPDATE;
    d:=public.case104_deadline_token(x.deadline_id,p_versions);old_d:=to_jsonb(d);
    IF d.status<>'Active' OR d.case_id<>p_case_id THEN RAISE EXCEPTION 'CASE104_DEADLINE_UNAVAILABLE'; END IF;
    IF x.extension_id IS NULL THEN
     INSERT INTO public.case_deadline_extensions(deadline_id,extension_no,requested_date,granted_until_date,note)
     VALUES(d.id,(SELECT coalesce(max(extension_no),0)+1 FROM public.case_deadline_extensions WHERE deadline_id=d.id),g.requested_on,day,coalesce(p_data->>'note',g.note)) RETURNING id INTO claimant;
     UPDATE public.case_extension_group_parties SET extension_id=claimant WHERE group_id=dst AND party_id=pid;
    ELSE
     IF NOT EXISTS(SELECT 1 FROM public.case_deadline_extensions e WHERE e.id=x.extension_id AND e.deleted_at IS NULL AND e.granted_until_date=d.current_due_date
      AND e.extension_no=(SELECT max(extension_no) FROM public.case_deadline_extensions WHERE deadline_id=d.id AND deleted_at IS NULL)) THEN RAISE EXCEPTION 'CASE104_EXTENSION_REVIEW_REQUIRED'; END IF;
     UPDATE public.case_deadline_extensions SET granted_until_date=day,note=coalesce(p_data->>'note',note),updated_at=clock_timestamp() WHERE id=x.extension_id;
    END IF;
    UPDATE public.case_deadlines SET current_due_date=day,updated_at=clock_timestamp() WHERE id=d.id RETURNING * INTO d;
    effects:=effects||jsonb_build_array(jsonb_build_object('party_id',pid,'before',old_d,'after',to_jsonb(d)));
   END LOOP;
   UPDATE public.case_extension_groups SET lifecycle='granted' WHERE id=dst;
  END IF;
  UPDATE public.case_extension_groups SET version=CASE WHEN (p_versions->>'entity')::integer=0 THEN 1 ELSE version+1 END,
   document_ref=CASE WHEN p_data ? 'document_ref' THEN nullif(p_data->>'document_ref','') ELSE document_ref END,note=CASE WHEN p_data ? 'note' THEN p_data->>'note' ELSE note END,updated_at=clock_timestamp(),updated_by=auth.uid() WHERE id=dst;

 ELSIF p_action IN('flow_start','flow_transition') THEN
  dst:=(p_data->>'id')::uuid;IF dst IS NULL THEN RAISE EXCEPTION 'CASE104_INVALID_INPUT'; END IF;
  SELECT * INTO i FROM public.case_flow_instances WHERE case_id=p_case_id AND track_key='main' FOR UPDATE;
  IF NOT EXISTS(SELECT 1 FROM public.case_defendant_representations WHERE case_id=p_case_id AND active) THEN RAISE EXCEPTION 'CASE104_PARTIES_REQUIRED'; END IF;
  IF NOT EXISTS(SELECT 1 FROM public.case_flow_stages WHERE template_id='civil_ordinary_defendant_v1' AND stage_key=p_data->>'stage') THEN RAISE EXCEPTION 'CASE104_INVALID_STAGE'; END IF;
  IF p_action='flow_start' THEN
   IF i.id IS NOT NULL OR (p_versions->>'flow')::integer IS DISTINCT FROM 0 THEN RAISE EXCEPTION 'CASE104_STALE'; END IF;
   IF p_data->'acknowledged' IS DISTINCT FROM 'true'::jsonb THEN RAISE EXCEPTION 'CASE104_CONFIRM_REQUIRED'; END IF;
   IF p_data->>'start_kind' IS NULL OR p_data->>'start_kind' NOT IN('new','cut_in') OR (p_data->>'start_kind'='new' AND p_data->>'stage'<>'D-CIV-01') THEN RAISE EXCEPTION 'CASE104_CUT_IN_REQUIRED'; END IF;
   INSERT INTO public.case_flow_instances(id,case_id,track_key,template_id,filing_method,current_stage,started_stage,start_kind,started_by,updated_by)
   VALUES(dst,p_case_id,'main','civil_ordinary_defendant_v1',p_data->>'filing_method',p_data->>'stage',p_data->>'stage',p_data->>'start_kind',auth.uid(),auth.uid()) RETURNING * INTO i;
   INSERT INTO public.case_flow_transitions(id,instance_id,template_id,sequence_no,event_kind,to_stage,to_lifecycle,actor_id,request_id,request_data)
   VALUES(gen_random_uuid(),i.id,i.template_id,1,'start',i.current_stage,i.lifecycle,auth.uid(),p_request_id,req);
  ELSE
   IF i.id IS DISTINCT FROM dst OR i.template_id<>'civil_ordinary_defendant_v1' OR i.lifecycle<>'active' OR (p_versions->>'flow')::integer IS DISTINCT FROM i.version THEN RAISE EXCEPTION 'CASE104_STALE'; END IF;
   IF p_data->'confirmed' IS DISTINCT FROM 'true'::jsonb THEN RAISE EXCEPTION 'CASE104_CONFIRM_REQUIRED'; END IF;
   before_stage:=i.current_stage;state:=i.lifecycle;
   SELECT CASE WHEN dest.ordinal=src.ordinal+1 THEN 'NEXT' WHEN dest.ordinal=src.ordinal THEN 'REPEAT' WHEN dest.ordinal>src.ordinal+1 THEN 'SKIP' ELSE 'RETURN' END INTO code
    FROM public.case_flow_stages src CROSS JOIN public.case_flow_stages dest WHERE src.template_id=i.template_id AND dest.template_id=i.template_id AND src.stage_key=i.current_stage AND dest.stage_key=p_data->>'stage';
   IF p_data ? 'corrects_id' THEN
    SELECT * INTO prev FROM public.case_flow_transitions WHERE instance_id=i.id ORDER BY sequence_no DESC LIMIT 1;
    IF (p_data->>'corrects_id')::uuid IS DISTINCT FROM prev.id THEN RAISE EXCEPTION 'CASE104_STALE'; END IF;code:='RETURN';
   END IF;
   IF code<>'NEXT' AND why IS NULL THEN RAISE EXCEPTION 'CASE104_REASON_REQUIRED'; END IF;
   UPDATE public.case_flow_instances SET current_stage=p_data->>'stage',version=version+1,updated_at=clock_timestamp(),updated_by=auth.uid() WHERE id=i.id RETURNING * INTO i;
   INSERT INTO public.case_flow_transitions(id,instance_id,template_id,sequence_no,event_kind,transition_code,from_stage,to_stage,from_lifecycle,to_lifecycle,reason,corrects_id,actor_id,request_id,request_data)
   VALUES(gen_random_uuid(),i.id,i.template_id,i.version,CASE WHEN p_data ? 'corrects_id' THEN 'correction' ELSE 'transition' END,code,before_stage,i.current_stage,state,i.lifecycle,why,(p_data->>'corrects_id')::uuid,auth.uid(),p_request_id,req);
  END IF;

 ELSIF p_action='next' THEN
  IF NOT EXISTS(SELECT 1 FROM public.case_defendant_representations WHERE case_id=p_case_id AND active) THEN RAISE EXCEPTION 'CASE104_PARTIES_REQUIRED'; END IF;
  IF NOT(p_data ? 'next' OR p_data ? 'assignments') THEN RAISE EXCEPTION 'CASE104_INVALID_INPUT'; END IF;
  IF p_data ? 'next' THEN
   pid:=(p_data->'next'->>'assignee_id')::uuid;
   IF pid IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.user_profiles WHERE id=pid AND active AND NOT must_change_password AND account_type='operational' AND assignable AND role IN('admin','partner','lawyer','assistant_lawyer','staff')) THEN RAISE EXCEPTION 'CASE104_PERSON_INELIGIBLE'; END IF;
   result:=public.case098_save(p_case_id,(p_versions->>'core')::integer,'next',p_data->'next');
  END IF;
  IF p_data ? 'assignments' THEN
   FOR entry IN SELECT value FROM jsonb_array_elements(p_data->'assignments') LOOP
    IF NOT EXISTS(SELECT 1 FROM public.user_profiles WHERE id=(entry->>'person_id')::uuid AND active AND NOT must_change_password AND account_type='operational' AND assignable AND role IN('admin','partner','lawyer','assistant_lawyer','staff')) THEN RAISE EXCEPTION 'CASE104_PERSON_INELIGIBLE'; END IF;
   END LOOP;
   result:=public.case098_save(p_case_id,CASE WHEN p_data ? 'next' THEN (result->'core'->>'version')::integer ELSE (p_versions->>'core')::integer END,'team',jsonb_build_object('assignments',p_data->'assignments'));
  END IF;
 END IF;

 -- Dependency and projection checks run before acknowledging success, not only at outer COMMIT.
 SET CONSTRAINTS case104_integrity IMMEDIATE;
 SET CONSTRAINTS case104_integrity DEFERRED;
 SELECT coalesce(array_agg(DISTINCT u.party_id ORDER BY u.party_id),'{}') INTO affected FROM unnest(affected) u(party_id) WHERE u.party_id IS NOT NULL;
 IF p_action='filing_void' THEN dst:=fid; END IF;
 new_facts:=(public.case104_read(p_case_id)-'history'-'transitions'-'stages'-'template')||jsonb_build_object('version',v+1);
 result:=jsonb_build_object('receipt_id',event_id,'request_id',p_request_id,'version',v+1,'entity_id',dst,'affected_parties',to_jsonb(affected),
  'deadline_effects',effects,'all_resolved',new_facts->'all_resolved','flow_inconsistency',new_facts->'flow_inconsistency','suggestion',new_facts->'suggestion');
 INSERT INTO public.case_service_events(id,case_id,party_id,action,actor_id,before_data,after_data,request_id,request_data)
 VALUES(event_id,p_case_id,NULL,'case104_'||p_action,auth.uid(),old_facts,new_facts||jsonb_build_object('version',v+1,'deadline_effects',effects,'result',result),p_request_id,req);
 INSERT INTO public.case_audit_logs(case_id,table_name,record_id,action,user_id,user_name,user_role,old_data,new_data,note)
 VALUES(p_case_id,CASE WHEN p_action LIKE 'filing_%' THEN 'case_answer_filings' WHEN p_action LIKE 'counterclaim_%' THEN 'case_counterclaims'
  WHEN p_action='extension' THEN 'case_extension_groups' WHEN p_action LIKE 'flow_%' THEN 'case_flow_instances' WHEN p_action LIKE 'service%' THEN 'case_service_attempts'
  WHEN p_action='deadline' THEN 'case_deadlines' WHEN p_action='next' THEN 'case_work_core' ELSE 'case_defendant_representations' END,
  coalesce(dst::text,p_case_id::text),'update',auth.uid(),coalesce(nullif(actor.staff_name,''),actor.full_name),actor.role,old_facts,new_facts||jsonb_build_object('receipt_id',event_id,'deadline_effects',effects),'case104_'||p_action||coalesce(': '||why,''));
 RETURN result;
EXCEPTION WHEN invalid_text_representation OR invalid_datetime_format OR datetime_field_overflow OR check_violation OR not_null_violation OR foreign_key_violation OR unique_violation THEN RAISE EXCEPTION 'CASE104_INVALID_INPUT';
END $function$

case099_save(bigint,uuid,integer,uuid,js.definition:
CREATE OR REPLACE FUNCTION public.case099_save(p_case_id bigint, p_id uuid, p_version integer, p_request_id uuid, p_data jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
 old_row public.case_proceedings; saved public.case_proceedings;
 hearing public.case_timeline; follow_hearing public.case_timeline; deadline public.case_deadlines;
 actor public.user_profiles; facts jsonb; followups jsonb; entry jsonb; person uuid;
 old_hearing jsonb; team jsonb; result jsonb; core_version integer; report_date date;
 request jsonb:=jsonb_build_object('case_id',p_case_id,'version',p_version,'data',p_data);
BEGIN
 IF NOT(public.case097_session_ready() AND public.can_view_case_data() AND public.case097_process_writer()) THEN RAISE EXCEPTION 'CASE099_FORBIDDEN' USING ERRCODE='42501'; END IF;
 IF p_id IS NULL OR p_request_id IS NULL OR p_version IS NULL OR p_version<0 OR jsonb_typeof(p_data) IS DISTINCT FROM 'object'
  OR EXISTS(SELECT 1 FROM jsonb_object_keys(p_data) k WHERE k NOT IN ('facts','followups','hearing_updated_at','core_version')) THEN RAISE EXCEPTION 'CASE099_INVALID_INPUT'; END IF;
 -- Same lock order as 098. Serializes report/follow-up creation within this Case.
 PERFORM 1 FROM public.cases WHERE id=p_case_id FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'CASE099_NOT_FOUND'; END IF;
 SELECT * INTO old_row FROM public.case_proceedings WHERE id=p_id FOR UPDATE;
 IF old_row.id IS NOT NULL THEN
  IF old_row.case_id<>p_case_id THEN RAISE EXCEPTION 'CASE099_NOT_FOUND'; END IF;
  IF old_row.last_request_id=p_request_id THEN
   IF old_row.last_request IS DISTINCT FROM request OR old_row.updated_by<>auth.uid() THEN RAISE EXCEPTION 'CASE099_REQUEST_CONFLICT'; END IF;
   RETURN public.case099_read(p_case_id);
  END IF;
 END IF;
 IF coalesce(old_row.version,0)<>p_version THEN RAISE EXCEPTION 'CASE099_STALE'; END IF;
 facts:=p_data->'facts'; followups:=coalesce(p_data->'followups','{}');
 IF jsonb_typeof(facts) IS DISTINCT FROM 'object' OR jsonb_typeof(followups) IS DISTINCT FROM 'object'
 OR EXISTS(SELECT 1 FROM jsonb_object_keys(facts) k WHERE k NOT IN ('kind','hearing_id','event_date','title','details','court_result','party_statement','note','document_ref'))
 OR EXISTS(SELECT 1 FROM jsonb_object_keys(followups) k WHERE k NOT IN ('hearing','deadline','next','current_actor')) THEN RAISE EXCEPTION 'CASE099_INVALID_INPUT'; END IF;
 IF old_row.id IS NOT NULL AND followups<>'{}' THEN RAISE EXCEPTION 'CASE099_FOLLOWUPS_ALREADY_SAVED'; END IF;
 IF old_row.id IS NOT NULL AND ((old_row.kind='hearing_report') IS DISTINCT FROM (facts->>'kind'='hearing_report') OR old_row.hearing_id IS DISTINCT FROM nullif(facts->>'hearing_id','')::uuid) THEN RAISE EXCEPTION 'CASE099_IDENTITY_FIXED'; END IF;
 report_date:=(facts->>'event_date')::date;
 IF facts->>'kind'='hearing_report' THEN
  SELECT * INTO hearing FROM public.case_timeline WHERE id=(facts->>'hearing_id')::uuid AND case_id=p_case_id FOR UPDATE;
  IF NOT FOUND OR hearing.deleted_at IS NOT NULL OR hearing.event_type<>'hearing' OR hearing.status='Cancelled' THEN RAISE EXCEPTION 'CASE099_HEARING_UNAVAILABLE'; END IF;
  IF old_row.id IS NULL THEN
   IF hearing.updated_at IS DISTINCT FROM (p_data->>'hearing_updated_at')::timestamptz THEN RAISE EXCEPTION 'CASE099_HEARING_STALE'; END IF;
   IF hearing.event_date IS NULL OR hearing.event_date !~ '^\d{4}-\d{2}-\d{2}$' OR hearing.event_date::date>(now() AT TIME ZONE 'Asia/Bangkok')::date THEN RAISE EXCEPTION 'CASE099_HEARING_NOT_HELD'; END IF;
   IF EXISTS(SELECT 1 FROM public.case_proceedings WHERE hearing_id=hearing.id) THEN RAISE EXCEPTION 'CASE099_REPORT_EXISTS'; END IF;
   report_date:=hearing.event_date::date;
  ELSIF report_date IS DISTINCT FROM old_row.event_date THEN RAISE EXCEPTION 'CASE099_IDENTITY_FIXED'; END IF;
 END IF;
 -- Explicitly selected assignment identities only, using the Phase 2A operational picker rule.
 FOR person IN SELECT v FROM (VALUES(nullif(followups->>'current_actor','')::uuid),(nullif(followups#>>'{next,assignee_id}','')::uuid)) x(v) WHERE v IS NOT NULL LOOP
  PERFORM 1 FROM public.user_profiles p WHERE p.id=person AND p.active IS TRUE AND p.account_type='operational' AND p.assignable IS TRUE
   AND p.must_change_password IS FALSE AND p.role IN ('admin','partner','lawyer','assistant_lawyer','staff') FOR SHARE;
  IF NOT FOUND THEN RAISE EXCEPTION 'CASE099_PERSON_INELIGIBLE'; END IF;
 END LOOP;
 IF followups ? 'current_actor' AND nullif(followups->>'current_actor','') IS NULL THEN RAISE EXCEPTION 'CASE099_INVALID_INPUT'; END IF;
 IF followups ? 'next' OR followups ? 'current_actor' THEN
  SELECT coalesce((SELECT version FROM public.case_work_core WHERE case_id=p_case_id),0) INTO core_version;
  IF core_version IS DISTINCT FROM (p_data->>'core_version')::integer THEN RAISE EXCEPTION 'CASE099_CORE_STALE'; END IF;
 END IF;
 SELECT * INTO actor FROM public.user_profiles WHERE id=auth.uid();
 IF old_row.id IS NULL AND hearing.id IS NOT NULL AND hearing.status IS DISTINCT FROM 'Done' THEN
  old_hearing:=to_jsonb(hearing);
  UPDATE public.case_timeline SET status='Done',updated_at=clock_timestamp() WHERE id=hearing.id RETURNING * INTO hearing;
  INSERT INTO public.case_audit_logs(case_id,table_name,record_id,action,user_id,user_name,user_role,old_data,new_data,note)
  VALUES(p_case_id,'case_timeline',hearing.id::text,'update',auth.uid(),coalesce(nullif(actor.staff_name,''),actor.full_name),actor.role,old_hearing,to_jsonb(hearing),'case099_hearing_done');
 END IF;
 IF followups ? 'hearing' THEN
  entry:=followups->'hearing';
  IF jsonb_typeof(entry) IS DISTINCT FROM 'object' OR EXISTS(SELECT 1 FROM jsonb_object_keys(entry) k WHERE k NOT IN ('date','time','title','note'))
   OR NOT coalesce(isfinite((entry->>'date')::date),false) OR nullif(btrim(entry->>'title'),'') IS NULL OR length(entry->>'title')>500
   OR (nullif(entry->>'time','') IS NOT NULL AND (entry->>'time') !~ '^([01][0-9]|2[0-3]):[0-5][0-9]$') THEN RAISE EXCEPTION 'CASE099_INVALID_HEARING'; END IF;
  INSERT INTO public.case_timeline(case_id,event_type,event_date,event_time,appointment_type,appointment_other,note,order_no,status)
  VALUES(p_case_id,'hearing',((entry->>'date')::date)::text,nullif(entry->>'time',''),'นัดอื่นๆ',btrim(entry->>'title'),nullif(entry->>'note',''),
   (SELECT coalesce(max(order_no),0)+1 FROM public.case_timeline WHERE case_id=p_case_id AND event_type='hearing'),'Scheduled') RETURNING * INTO follow_hearing;
  INSERT INTO public.case_audit_logs(case_id,table_name,record_id,action,user_id,user_name,user_role,new_data,note)
  VALUES(p_case_id,'case_timeline',follow_hearing.id::text,'create',auth.uid(),coalesce(nullif(actor.staff_name,''),actor.full_name),actor.role,to_jsonb(follow_hearing),'case099_followup');
 END IF;
 IF followups ? 'deadline' THEN
  entry:=followups->'deadline';
  IF jsonb_typeof(entry) IS DISTINCT FROM 'object' OR EXISTS(SELECT 1 FROM jsonb_object_keys(entry) k WHERE k NOT IN ('date','title','note'))
   OR NOT coalesce(isfinite((entry->>'date')::date),false) OR nullif(btrim(entry->>'title'),'') IS NULL OR length(entry->>'title')>500 THEN RAISE EXCEPTION 'CASE099_INVALID_DEADLINE'; END IF;
  INSERT INTO public.case_deadlines(case_id,deadline_type,deadline_other,original_due_date,current_due_date,note,status,order_no)
  VALUES(p_case_id,'other',btrim(entry->>'title'),(entry->>'date')::date,(entry->>'date')::date,nullif(entry->>'note',''),'Active',
   (SELECT coalesce(max(order_no),0)+1 FROM public.case_deadlines WHERE case_id=p_case_id)) RETURNING * INTO deadline;
  INSERT INTO public.case_audit_logs(case_id,table_name,record_id,action,user_id,user_name,user_role,new_data,note)
  VALUES(p_case_id,'case_deadlines',deadline.id::text,'create',auth.uid(),coalesce(nullif(actor.staff_name,''),actor.full_name),actor.role,to_jsonb(deadline),'case099_followup');
 END IF;
 IF followups ? 'next' THEN
  IF followups#>>'{next,mode}' NOT IN ('manual','task') OR followups#>>'{next,mode}' IS NULL THEN RAISE EXCEPTION 'CASE099_INVALID_INPUT'; END IF;
  result:=public.case098_save(p_case_id,core_version,'next',followups->'next'); core_version:=(result#>>'{core,version}')::integer;
 END IF;
 IF followups ? 'current_actor' THEN
  SELECT coalesce(jsonb_agg(jsonb_build_object('person_id',person_id,'team_role',team_role) ORDER BY team_role,person_id),'[]') INTO team FROM public.case_team_assignments WHERE case_id=p_case_id AND team_role<>'current_actor';
  result:=public.case098_save(p_case_id,core_version,'team',jsonb_build_object('assignments',team||jsonb_build_array(jsonb_build_object('person_id',followups->>'current_actor','team_role','current_actor'))));
 END IF;
 IF old_row.id IS NULL THEN
  INSERT INTO public.case_proceedings(id,case_id,kind,hearing_id,event_date,title,details,court_result,party_statement,note,document_ref,next_hearing_id,deadline_id,handoff,last_request_id,last_request,created_by,updated_by)
  VALUES(p_id,p_case_id,facts->>'kind',nullif(facts->>'hearing_id','')::uuid,report_date,btrim(facts->>'title'),btrim(facts->>'details'),nullif(facts->>'court_result',''),nullif(facts->>'party_statement',''),nullif(facts->>'note',''),nullif(facts->>'document_ref',''),follow_hearing.id,deadline.id,
   CASE WHEN result IS NULL THEN '{}'::jsonb ELSE jsonb_build_object('requested',followups-'hearing'-'deadline','core',result->'core','team',result->'team',
    'people',(SELECT coalesce(jsonb_agg(v),'[]') FROM jsonb_array_elements(result->'people') v WHERE v->>'id'=result#>>'{core,next_assignee_id}' OR v->>'id'=followups->>'current_actor'),
    'task',(SELECT v FROM jsonb_array_elements(result->'tasks') v WHERE v->>'id'=result#>>'{core,next_task_id}')) END,p_request_id,request,auth.uid(),auth.uid()) RETURNING * INTO saved;
 ELSE
  UPDATE public.case_proceedings SET kind=facts->>'kind',event_date=report_date,title=btrim(facts->>'title'),details=btrim(facts->>'details'),court_result=nullif(facts->>'court_result',''),party_statement=nullif(facts->>'party_statement',''),note=nullif(facts->>'note',''),document_ref=nullif(facts->>'document_ref',''),version=version+1,last_request_id=p_request_id,last_request=request,updated_by=auth.uid(),updated_at=clock_timestamp() WHERE id=p_id RETURNING * INTO saved;
 END IF;
 INSERT INTO public.case_audit_logs(case_id,table_name,record_id,action,user_id,user_name,user_role,old_data,new_data,note)
 VALUES(p_case_id,'case_proceedings',p_id::text,CASE WHEN old_row.id IS NULL THEN 'create' ELSE 'update' END,auth.uid(),coalesce(nullif(actor.staff_name,''),actor.full_name),actor.role,
  CASE WHEN old_row.id IS NULL THEN NULL ELSE to_jsonb(old_row)-'last_request'-'last_request_id' END,to_jsonb(saved)-'last_request'-'last_request_id','case099_saved');
 RETURN public.case099_read(p_case_id);
EXCEPTION WHEN invalid_text_representation OR invalid_datetime_format OR datetime_field_overflow OR check_violation OR unique_violation OR not_null_violation OR foreign_key_violation THEN RAISE EXCEPTION 'CASE099_INVALID_INPUT';
END $function$

case104_counterclaim_write(bigint,text,j.definition:
CREATE OR REPLACE FUNCTION public.case104_counterclaim_write(p_case_id bigint, p_action text, p_data jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE c public.case_counterclaims; f public.case_answer_filings; ids uuid[]; targets uuid[]; dst uuid; v integer; why text; day date; BEGIN
 IF p_action IS NULL OR p_action NOT IN('create','correct','void','relink') THEN RAISE EXCEPTION 'CASE104_INVALID_INPUT'; END IF;
 IF jsonb_typeof(p_data) IS DISTINCT FROM 'object' OR EXISTS(SELECT 1 FROM jsonb_object_keys(p_data) k WHERE k NOT IN('id','version','filing_id','filed_on','document_ref','note','claimants','targets','reason','replacement_id'))
 THEN RAISE EXCEPTION 'CASE104_INVALID_INPUT'; END IF;
 dst:=(p_data->>'id')::uuid; why:=nullif(btrim(p_data->>'reason'),'');
 IF dst IS NULL THEN RAISE EXCEPTION 'CASE104_INVALID_INPUT'; END IF;
 SELECT * INTO c FROM public.case_counterclaims WHERE id=dst FOR UPDATE;
 IF p_action='create' THEN
  IF c.id IS NOT NULL OR (p_data->>'version')::integer IS DISTINCT FROM 0 THEN RAISE EXCEPTION 'CASE104_STALE'; END IF;
 ELSE
  IF c.id IS NULL OR c.case_id<>p_case_id OR c.lifecycle<>'active' OR (p_data->>'version')::integer IS DISTINCT FROM c.version THEN RAISE EXCEPTION 'CASE104_STALE'; END IF;
  IF why IS NULL THEN RAISE EXCEPTION 'CASE104_REASON_REQUIRED'; END IF;
 END IF;
 IF p_action='void' THEN
  IF EXISTS(SELECT 1 FROM jsonb_object_keys(p_data) k WHERE k NOT IN('id','version','reason')) THEN RAISE EXCEPTION 'CASE104_INVALID_INPUT'; END IF;
  UPDATE public.case_counterclaims SET lifecycle='void',reason=why,version=version+1,updated_at=clock_timestamp(),updated_by=auth.uid() WHERE id=dst;
  RETURN dst;
 END IF;
 IF p_action NOT IN('create','correct','relink') THEN RAISE EXCEPTION 'CASE104_INVALID_INPUT'; END IF;
 SELECT * INTO f FROM public.case_answer_filings WHERE id=coalesce((p_data->>'filing_id')::uuid,c.filing_id) AND case_id=p_case_id AND lifecycle='active' FOR UPDATE;
 IF f.id IS NULL THEN RAISE EXCEPTION 'CASE104_FILING_UNAVAILABLE'; END IF;
 IF p_data ? 'claimants' OR p_action='create' THEN ids:=public.case104_parties(p_case_id,p_data->'claimants','defendant');
 ELSE SELECT array_agg(party_id ORDER BY party_id) INTO ids FROM public.case_counterclaim_parties WHERE counterclaim_id=c.id AND coverage_version=c.coverage_version AND side='claimant'; END IF;
 IF p_data ? 'targets' OR p_action='create' THEN targets:=public.case104_parties(p_case_id,p_data->'targets','plaintiff',false);
 ELSE SELECT array_agg(party_id ORDER BY party_id) INTO targets FROM public.case_counterclaim_parties WHERE counterclaim_id=c.id AND coverage_version=c.coverage_version AND side='target'; END IF;
 IF cardinality(ids) IS NULL OR cardinality(targets) IS NULL OR EXISTS(SELECT 1 FROM unnest(ids) p WHERE NOT EXISTS(SELECT 1 FROM public.case_answer_filing_parties a WHERE a.filing_id=f.id AND a.coverage_version=f.coverage_version AND a.party_id=p)) THEN RAISE EXCEPTION 'CASE104_COUNTERCLAIM_COVERAGE'; END IF;
 day:=coalesce((p_data->>'filed_on')::date,c.filed_on);
 IF day IS NULL OR NOT isfinite(day) OR day>(current_timestamp AT TIME ZONE 'Asia/Bangkok')::date THEN RAISE EXCEPTION 'CASE104_INVALID_DATE'; END IF;
 IF p_action='create' THEN
  INSERT INTO public.case_counterclaims(id,case_id,filing_id,filed_on,document_ref,note,recorded_by,updated_by)
  VALUES(dst,p_case_id,f.id,day,nullif(p_data->>'document_ref',''),p_data->>'note',auth.uid(),auth.uid());v:=1;
 ELSE
  IF p_data ? 'replacement_id' THEN
   dst:=(p_data->>'replacement_id')::uuid;
   IF dst IS NULL OR EXISTS(SELECT 1 FROM public.case_counterclaims WHERE id=dst) THEN RAISE EXCEPTION 'CASE104_INVALID_INPUT'; END IF;
   UPDATE public.case_counterclaims SET lifecycle='corrected',version=version+1,reason=why,updated_at=clock_timestamp(),updated_by=auth.uid() WHERE id=c.id;
   INSERT INTO public.case_counterclaims(id,case_id,filing_id,filed_on,document_ref,note,replaces_id,reason,recorded_by,updated_by)
   VALUES(dst,p_case_id,f.id,day,CASE WHEN p_data ? 'document_ref' THEN nullif(p_data->>'document_ref','') ELSE c.document_ref END,coalesce(p_data->>'note',c.note),c.id,why,auth.uid(),auth.uid());v:=1;
  ELSE
   v:=c.coverage_version+1;
   UPDATE public.case_counterclaims SET filing_id=f.id,filed_on=day,document_ref=CASE WHEN p_data ? 'document_ref' THEN nullif(p_data->>'document_ref','') ELSE document_ref END,
    note=CASE WHEN p_data ? 'note' THEN p_data->>'note' ELSE note END,reason=why,version=version+1,coverage_version=v,updated_at=clock_timestamp(),updated_by=auth.uid() WHERE id=c.id;
  END IF;
 END IF;
 INSERT INTO public.case_counterclaim_parties SELECT dst,v,x,'claimant' FROM unnest(ids) x;
 INSERT INTO public.case_counterclaim_parties SELECT dst,v,x,'target' FROM unnest(targets) x;
 RETURN dst;
END $function$

case101_save(bigint,uuid,integer,uuid,te.definition:
CREATE OR REPLACE FUNCTION public.case101_save(p_case_id bigint, p_instance_id uuid, p_version integer, p_request_id uuid, p_action text, p_data jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE i public.case_flow_instances; prev public.case_flow_transitions; retried public.case_flow_transitions; actor public.user_profiles;
 target text; method text; why text; code text; state text; from_pos integer; to_pos integer; correcting uuid; eid uuid:=gen_random_uuid();
 old_facts jsonb; request jsonb:=jsonb_build_object('case_id',p_case_id,'instance_id',p_instance_id,'version',p_version,'action',p_action,'data',p_data);
BEGIN
 IF NOT(public.case097_session_ready() AND public.can_view_case_data() AND public.case097_process_writer()) THEN RAISE EXCEPTION 'CASE101_FORBIDDEN' USING ERRCODE='42501'; END IF;
 SELECT * INTO actor FROM public.user_profiles WHERE id=auth.uid();
 IF p_instance_id IS NULL OR p_request_id IS NULL OR p_version IS NULL OR p_version<0 OR p_action IS NULL OR p_action NOT IN('start','advance','pause','resume','exit','correct') OR jsonb_typeof(p_data) IS DISTINCT FROM 'object' THEN RAISE EXCEPTION 'CASE101_INVALID_INPUT'; END IF;
 IF p_action='start' AND actor.role NOT IN('admin','partner','lawyer') THEN RAISE EXCEPTION 'CASE101_FORBIDDEN' USING ERRCODE='42501'; END IF;
 -- Serialize the one Main Track and immutable event receipt under the existing Case identity.
 PERFORM 1 FROM public.cases WHERE id=p_case_id FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'CASE101_NOT_FOUND'; END IF;
 SELECT * INTO retried FROM public.case_flow_transitions WHERE request_id=p_request_id;
 IF retried.id IS NOT NULL THEN
  IF retried.actor_id<>auth.uid() OR retried.request_data IS DISTINCT FROM request THEN RAISE EXCEPTION 'CASE101_REQUEST_CONFLICT'; END IF;
  RETURN public.case101_read(p_case_id);
 END IF;
 SELECT * INTO i FROM public.case_flow_instances WHERE case_id=p_case_id AND track_key='main' FOR UPDATE;
 why:=nullif(btrim(p_data->>'reason'),''); target:=p_data->>'stage';
 IF p_action='start' THEN
  IF EXISTS(SELECT 1 FROM jsonb_object_keys(p_data) k WHERE k NOT IN('stage','filing_method','acknowledged','start_kind')) OR p_data->'acknowledged' IS DISTINCT FROM 'true'::jsonb OR p_data->>'start_kind' IS NULL OR p_data->>'start_kind' NOT IN('new','cut_in') THEN RAISE EXCEPTION 'CASE101_INVALID_INPUT'; END IF;
  IF i.id IS NOT NULL OR p_version<>0 THEN RAISE EXCEPTION 'CASE101_STALE'; END IF;
  IF p_data->>'start_kind'='new' AND target IS DISTINCT FROM 'prepare_claim' THEN RAISE EXCEPTION 'CASE101_CUT_IN_REQUIRED'; END IF;
  method:=p_data->>'filing_method';
  INSERT INTO public.case_flow_instances(id,case_id,track_key,template_id,filing_method,current_stage,started_stage,start_kind,started_by,updated_by)
  VALUES(p_instance_id,p_case_id,'main','civil_ordinary_plaintiff_v1',method,target,target,p_data->>'start_kind',auth.uid(),auth.uid()) RETURNING * INTO i;
  INSERT INTO public.case_flow_transitions(id,instance_id,template_id,sequence_no,event_kind,to_stage,to_lifecycle,actor_id,request_id,request_data)
  VALUES(eid,i.id,i.template_id,1,'start',target,'active',auth.uid(),p_request_id,request);
 ELSE
  IF i.id IS DISTINCT FROM p_instance_id THEN RAISE EXCEPTION 'CASE101_NOT_FOUND'; END IF;
  IF i.version<>p_version THEN RAISE EXCEPTION 'CASE101_STALE'; END IF;
  IF EXISTS(SELECT 1 FROM jsonb_object_keys(p_data) k WHERE k NOT IN('stage','reason','corrects_id')) THEN RAISE EXCEPTION 'CASE101_INVALID_INPUT'; END IF;
  IF p_action<>'correct' AND p_data ? 'corrects_id' THEN RAISE EXCEPTION 'CASE101_INVALID_INPUT'; END IF;
  SELECT * INTO prev FROM public.case_flow_transitions WHERE instance_id=i.id ORDER BY sequence_no DESC LIMIT 1;
  old_facts:=to_jsonb(i); state:=i.lifecycle;
  IF p_action='correct' THEN
   correcting:=(p_data->>'corrects_id')::uuid;
   IF correcting IS NULL OR correcting<>prev.id THEN RAISE EXCEPTION 'CASE101_STALE'; END IF;
   -- Correct the latest fact, preserve its original event, restore its prior lifecycle.
   state:=coalesce(prev.from_lifecycle,'active'); code:='RETURN';
  ELSIF p_action='pause' THEN
   IF i.lifecycle<>'active' THEN RAISE EXCEPTION 'CASE101_STATE'; END IF; state:='paused';code:='PAUSE';
  ELSIF p_action='resume' THEN
   IF i.lifecycle<>'paused' THEN RAISE EXCEPTION 'CASE101_STATE'; END IF; state:='active';code:='RETURN';
  ELSIF p_action='exit' THEN
   IF i.lifecycle='exited' THEN RAISE EXCEPTION 'CASE101_STATE'; END IF; state:='exited';code:='EXIT';
  ELSE
   IF i.lifecycle<>'active' THEN RAISE EXCEPTION 'CASE101_STATE'; END IF;
   SELECT ordinal INTO from_pos FROM public.case_flow_stages WHERE template_id=i.template_id AND stage_key=i.current_stage;
   SELECT ordinal INTO to_pos FROM public.case_flow_stages WHERE template_id=i.template_id AND stage_key=target;
   IF to_pos IS NULL THEN RAISE EXCEPTION 'CASE101_INVALID_INPUT'; END IF;
   code:=CASE WHEN to_pos=from_pos+1 THEN 'NEXT' WHEN to_pos=from_pos THEN 'REPEAT' WHEN to_pos>from_pos+1 THEN 'SKIP' ELSE 'RETURN' END;
  END IF;
  IF p_action IN('pause','resume','exit') THEN
   IF target IS NOT NULL AND target<>i.current_stage THEN RAISE EXCEPTION 'CASE101_INVALID_INPUT'; END IF;target:=i.current_stage;
  END IF;
  IF (code<>'NEXT' OR p_action='correct') AND why IS NULL THEN RAISE EXCEPTION 'CASE101_REASON_REQUIRED'; END IF;
  UPDATE public.case_flow_instances SET current_stage=target,lifecycle=state,version=version+1,updated_at=clock_timestamp(),updated_by=auth.uid() WHERE id=i.id RETURNING * INTO i;
  INSERT INTO public.case_flow_transitions(id,instance_id,template_id,sequence_no,event_kind,transition_code,from_stage,to_stage,from_lifecycle,to_lifecycle,reason,corrects_id,actor_id,request_id,request_data)
  VALUES(eid,i.id,i.template_id,i.version,CASE WHEN p_action='correct' THEN 'correction' ELSE 'transition' END,code,old_facts->>'current_stage',target,old_facts->>'lifecycle',state,why,correcting,auth.uid(),p_request_id,request);
 END IF;
 INSERT INTO public.case_audit_logs(case_id,table_name,record_id,action,user_id,user_name,user_role,old_data,new_data,note)
 VALUES(p_case_id,'case_flow_instances',i.id::text,CASE WHEN p_action='start' THEN 'create' ELSE 'update' END,auth.uid(),coalesce(nullif(actor.staff_name,''),actor.full_name),actor.role,old_facts,to_jsonb(i)||jsonb_build_object('transition_id',eid,'reason',why),'case101_'||p_action);
 RETURN public.case101_read(p_case_id);
EXCEPTION WHEN invalid_text_representation OR check_violation OR not_null_violation OR foreign_key_violation OR unique_violation THEN RAISE EXCEPTION 'CASE101_INVALID_INPUT';
END $function$

case102_save(bigint,uuid,integer,uuid,te.definition:
CREATE OR REPLACE FUNCTION public.case102_save(p_case_id bigint, p_party_id uuid, p_version integer, p_request_id uuid, p_action text, p_data jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE c public.case_service_controls; a public.case_service_attempts; d public.case_deadlines; f public.case_flow_instances; actor public.user_profiles; receipt public.case_service_events;
 old_facts jsonb; new_facts jsonb; deadline_before jsonb; deadline_after jsonb; flow_before jsonb; next_before jsonb; next_after jsonb;
 req jsonb:=jsonb_build_object('case_id',p_case_id,'party_id',p_party_id,'version',p_version,'action',p_action,'data',p_data);
 allowed text[]; why text; due date; event_day date; today date:=(current_timestamp AT TIME ZONE 'Asia/Bangkok')::date; target uuid; person uuid; did uuid; attempts_id uuid; dst text;
BEGIN
 IF NOT(public.case097_session_ready() AND public.can_view_case_data() AND public.case097_process_writer()) THEN RAISE EXCEPTION 'CASE102_FORBIDDEN' USING ERRCODE='42501'; END IF;
 SELECT * INTO actor FROM public.user_profiles WHERE id=auth.uid();
 IF p_request_id IS NULL OR p_version IS NULL OR p_version<0 OR jsonb_typeof(p_data) IS DISTINCT FROM 'object' OR p_action IS NULL THEN RAISE EXCEPTION 'CASE102_INVALID_INPUT'; END IF;
 allowed:=CASE p_action
 WHEN 'attempt' THEN ARRAY['attempt_id','method','attempted_on','result','failure_kind','failure_reason','note','confirm_lawful']
 WHEN 'void' THEN ARRAY['attempt_id','reason']
 WHEN 'lawful' THEN ARRAY['attempt_id','confirmed']
 WHEN 'required' THEN ARRAY['required','reason']
 WHEN 'deadline' THEN ARRAY['kind','due','confirmed','existing_id','reason','expected_due','expected_updated_at']
 WHEN 'answer' THEN ARRAY['date','expected_due','expected_updated_at']
 WHEN 'absence' THEN ARRAY['hearing_id','confirmed']
 WHEN 'next' THEN ARRAY['core_version','next']
 WHEN 'advance' THEN ARRAY['flow_version','confirmed']
 WHEN 'branch' THEN ARRAY['flow_version','confirmed','reason'] END;
 IF allowed IS NULL OR EXISTS(SELECT 1 FROM jsonb_object_keys(p_data) k WHERE NOT(k=ANY(allowed))) THEN RAISE EXCEPTION 'CASE102_INVALID_INPUT'; END IF;
 IF p_action IN('lawful','required','deadline','answer','absence','advance','branch','void') AND actor.role NOT IN('lawyer','partner','admin') THEN RAISE EXCEPTION 'CASE102_LAWYER_REQUIRED' USING ERRCODE='42501'; END IF;
 PERFORM 1 FROM public.cases WHERE id=p_case_id FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'CASE102_NOT_FOUND'; END IF;
 SELECT * INTO receipt FROM public.case_service_events WHERE request_id=p_request_id;
 IF receipt.id IS NOT NULL THEN
  IF receipt.actor_id<>auth.uid() OR receipt.request_data IS DISTINCT FROM req THEN RAISE EXCEPTION 'CASE102_REQUEST_CONFLICT'; END IF;
  RETURN public.case102_read(p_case_id);
 END IF;
 SELECT * INTO f FROM public.case_flow_instances WHERE case_id=p_case_id AND track_key='main' FOR UPDATE;
 IF f.id IS NULL OR f.template_id<>'civil_ordinary_plaintiff_v1' OR f.lifecycle<>'active' THEN RAISE EXCEPTION 'CASE102_PILOT_REQUIRED'; END IF;
 IF p_action IN('advance','branch') THEN
  IF p_party_id IS NOT NULL OR p_version<>0 OR (p_data->>'flow_version')::integer IS DISTINCT FROM f.version THEN RAISE EXCEPTION 'CASE102_STALE'; END IF;
  IF p_data->'confirmed' IS DISTINCT FROM 'true'::jsonb THEN RAISE EXCEPTION 'CASE102_CONFIRM_REQUIRED'; END IF;
  -- All currently required live defendants, never inferred from a display name.
  IF NOT EXISTS(SELECT 1 FROM public.parties p LEFT JOIN public.case_service_controls s ON s.party_id=p.id WHERE p.case_id=p_case_id AND p.role='defendant' AND p.deleted_at IS NULL AND coalesce(s.required,true))
   OR EXISTS(SELECT 1 FROM public.parties p LEFT JOIN public.case_service_controls s ON s.party_id=p.id LEFT JOIN public.case_service_attempts x ON x.id=s.lawful_attempt_id
    WHERE p.case_id=p_case_id AND p.role='defendant' AND p.deleted_at IS NULL AND coalesce(s.required,true) AND (s.lawful_attempt_id IS NULL OR x.result IS DISTINCT FROM 'served')) THEN RAISE EXCEPTION 'CASE102_NOT_ALL_LAWFUL'; END IF;
  flow_before:=to_jsonb(f);
  IF p_action='advance' THEN
   IF f.current_stage<>'service' THEN RAISE EXCEPTION 'CASE102_FLOW_STATE'; END IF;
   PERFORM public.case101_save(p_case_id,f.id,f.version,p_request_id,'advance','{"stage":"defence"}'::jsonb);
  ELSE
   why:=nullif(btrim(p_data->>'reason'),'');
   IF why IS NULL THEN RAISE EXCEPTION 'CASE102_REASON_REQUIRED'; END IF;
   IF f.current_stage NOT IN('service','defence') THEN RAISE EXCEPTION 'CASE102_FLOW_STATE'; END IF;
   -- This conservative case-wide branch requires explicit nonappearance evidence for every required defendant.
   IF EXISTS(SELECT 1 FROM public.parties p JOIN public.case_service_controls s ON s.party_id=p.id LEFT JOIN public.case_timeline h ON h.id=s.absent_hearing_id
    WHERE p.case_id=p_case_id AND p.role='defendant' AND p.deleted_at IS NULL AND s.required AND (s.answer_filed_on IS NOT NULL OR h.id IS NULL OR h.deleted_at IS NOT NULL OR h.status='Cancelled')) THEN RAISE EXCEPTION 'CASE102_BRANCH_EVIDENCE_REQUIRED'; END IF;
   dst:='evidence';
   UPDATE public.case_flow_instances SET current_stage=dst,version=version+1,updated_at=clock_timestamp(),updated_by=auth.uid() WHERE id=f.id;
   INSERT INTO public.case_flow_transitions(id,instance_id,template_id,sequence_no,event_kind,transition_code,from_stage,to_stage,from_lifecycle,to_lifecycle,reason,actor_id,request_id,request_data)
   VALUES(gen_random_uuid(),f.id,f.template_id,f.version+1,'transition','BRANCH',f.current_stage,dst,'active','active',why,auth.uid(),p_request_id,req);
   INSERT INTO public.case_audit_logs(case_id,table_name,record_id,action,user_id,user_name,user_role,old_data,new_data,note)
   SELECT p_case_id,'case_flow_instances',i.id::text,'update',auth.uid(),coalesce(nullif(actor.staff_name,''),actor.full_name),actor.role,flow_before,to_jsonb(i),'case102_branch' FROM public.case_flow_instances i WHERE id=f.id;
  END IF;
  SELECT to_jsonb(i) INTO new_facts FROM public.case_flow_instances i WHERE id=f.id;old_facts:=flow_before;
 ELSE
  PERFORM 1 FROM public.parties WHERE id=p_party_id AND case_id=p_case_id AND role='defendant' AND deleted_at IS NULL FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'CASE102_PARTY_UNAVAILABLE'; END IF;
  SELECT * INTO c FROM public.case_service_controls WHERE party_id=p_party_id FOR UPDATE;
  IF coalesce(c.version,0)<>p_version THEN RAISE EXCEPTION 'CASE102_STALE'; END IF;
  old_facts:=jsonb_build_object('control',to_jsonb(c),'attempts',(SELECT coalesce(jsonb_agg(to_jsonb(x) ORDER BY id),'[]') FROM public.case_service_attempts x WHERE party_id=p_party_id));
  IF c.party_id IS NULL THEN INSERT INTO public.case_service_controls(party_id,case_id,updated_by) VALUES(p_party_id,p_case_id,auth.uid()) RETURNING * INTO c; END IF;
  why:=nullif(btrim(p_data->>'reason'),'');
  IF p_action='attempt' THEN
   attempts_id:=nullif(p_data->>'attempt_id','')::uuid;
   IF attempts_id IS NOT NULL THEN
    SELECT * INTO a FROM public.case_service_attempts WHERE id=attempts_id AND party_id=p_party_id FOR UPDATE;
    IF a.id IS NULL OR a.result<>'pending' OR c.lawful_attempt_id=a.id THEN RAISE EXCEPTION 'CASE102_ATTEMPT_FINAL'; END IF;
   END IF;
   event_day:=nullif(p_data->>'attempted_on','')::date;
   IF p_data->>'result' IS NULL OR p_data->>'result' NOT IN('pending','served','failed')
    OR (event_day IS NOT NULL AND (NOT isfinite(event_day) OR event_day>today))
    OR (nullif(p_data->>'method','') IS NOT NULL AND p_data->>'method' NOT IN('normal','posting','electronic','other'))
    OR (p_data->>'result' IN('pending','served') AND (event_day IS NULL OR nullif(p_data->>'method','') IS NULL))
    THEN RAISE EXCEPTION 'CASE102_INVALID_INPUT'; END IF;
   -- Optional atomic confirmation for the result-first UI; legacy callers retain explicit lawful action.
   IF p_data ? 'confirm_lawful' THEN
    IF p_data->'confirm_lawful' IS DISTINCT FROM 'true'::jsonb OR p_data->>'result'<>'served' THEN RAISE EXCEPTION 'CASE102_INVALID_INPUT'; END IF;
    IF actor.role NOT IN('lawyer','partner','admin') THEN RAISE EXCEPTION 'CASE102_LAWYER_REQUIRED' USING ERRCODE='42501'; END IF;
    IF c.lawful_attempt_id IS NOT NULL THEN RAISE EXCEPTION 'CASE102_ATTEMPT_FINAL'; END IF;
   END IF;
   IF attempts_id IS NULL THEN
    INSERT INTO public.case_service_attempts(id,party_id,case_id,method,attempted_on,result,failure_kind,failure_reason,note,recorded_by,updated_by)
    VALUES(gen_random_uuid(),p_party_id,p_case_id,nullif(p_data->>'method',''),event_day,p_data->>'result',nullif(p_data->>'failure_kind',''),nullif(btrim(p_data->>'failure_reason'),''),nullif(btrim(p_data->>'note'),''),auth.uid(),auth.uid()) RETURNING * INTO a;
   ELSE
    UPDATE public.case_service_attempts SET method=nullif(p_data->>'method',''),attempted_on=event_day,result=p_data->>'result',failure_kind=nullif(p_data->>'failure_kind',''),failure_reason=nullif(btrim(p_data->>'failure_reason'),''),note=nullif(btrim(p_data->>'note'),''),updated_at=clock_timestamp(),updated_by=auth.uid() WHERE id=attempts_id RETURNING * INTO a;
   END IF;
   IF p_data->'confirm_lawful'='true'::jsonb THEN
    UPDATE public.case_service_controls SET lawful_attempt_id=a.id,lawful_at=clock_timestamp(),lawful_by=auth.uid() WHERE party_id=p_party_id;
   END IF;
  ELSIF p_action='lawful' THEN
   IF p_data->'confirmed' IS DISTINCT FROM 'true'::jsonb THEN RAISE EXCEPTION 'CASE102_CONFIRM_REQUIRED'; END IF;
   SELECT * INTO a FROM public.case_service_attempts WHERE id=(p_data->>'attempt_id')::uuid AND party_id=p_party_id FOR UPDATE;
   IF a.id IS NULL OR a.result<>'served' OR c.lawful_attempt_id IS NOT NULL THEN RAISE EXCEPTION 'CASE102_ATTEMPT_FINAL'; END IF;
   UPDATE public.case_service_controls SET lawful_attempt_id=a.id,lawful_at=clock_timestamp(),lawful_by=auth.uid() WHERE party_id=p_party_id;
  ELSIF p_action='void' THEN
   IF why IS NULL THEN RAISE EXCEPTION 'CASE102_REASON_REQUIRED'; END IF;
   SELECT * INTO a FROM public.case_service_attempts WHERE id=(p_data->>'attempt_id')::uuid AND party_id=p_party_id FOR UPDATE;
   IF a.id IS NULL OR a.result='void' THEN RAISE EXCEPTION 'CASE102_ATTEMPT_FINAL'; END IF;
   IF c.lawful_attempt_id=a.id THEN
    IF c.answer_filed_on IS NOT NULL OR EXISTS(SELECT 1 FROM public.case_deadlines WHERE id IN(c.answer_deadline_id,c.default_deadline_id) AND deleted_at IS NULL AND status IS DISTINCT FROM 'Cancelled') THEN RAISE EXCEPTION 'CASE102_DEADLINE_REVIEW_REQUIRED'; END IF;
    UPDATE public.case_service_controls SET lawful_attempt_id=NULL,lawful_at=NULL,lawful_by=NULL,answer_deadline_id=NULL,default_deadline_id=NULL,absent_hearing_id=NULL WHERE party_id=p_party_id;
   END IF;
   UPDATE public.case_service_attempts SET result='void',void_reason=why,updated_at=clock_timestamp(),updated_by=auth.uid() WHERE id=a.id;
  ELSIF p_action='required' THEN
   IF jsonb_typeof(p_data->'required') IS DISTINCT FROM 'boolean' OR why IS NULL THEN RAISE EXCEPTION 'CASE102_REASON_REQUIRED'; END IF;
   UPDATE public.case_service_controls SET required=(p_data->>'required')::boolean,exemption_reason=why WHERE party_id=p_party_id;
  ELSIF p_action='deadline' THEN
   IF p_data->'confirmed' IS DISTINCT FROM 'true'::jsonb THEN RAISE EXCEPTION 'CASE102_CONFIRM_REQUIRED'; END IF;
   IF p_data->>'kind' IS NULL OR p_data->>'kind' NOT IN('answer','default','court') THEN RAISE EXCEPTION 'CASE102_INVALID_INPUT'; END IF;
   IF p_data->>'kind' IN('answer','default') AND (c.lawful_attempt_id IS NULL OR c.answer_filed_on IS NOT NULL) THEN RAISE EXCEPTION 'CASE102_LAWFUL_REQUIRED'; END IF;
   IF p_data->>'kind'='answer' AND c.answer_deadline_id IS NOT NULL OR p_data->>'kind'='default' AND c.default_deadline_id IS NOT NULL THEN RAISE EXCEPTION 'CASE102_DEADLINE_LINKED'; END IF;
   IF p_data->>'kind'='default' THEN
    SELECT * INTO d FROM public.case_deadlines WHERE id=c.answer_deadline_id AND case_id=p_case_id AND deleted_at IS NULL AND status='Active' FOR UPDATE;
    IF d.id IS NULL OR d.current_due_date IS NULL OR d.current_due_date>=today THEN RAISE EXCEPTION 'CASE102_NOT_OVERDUE'; END IF;
    IF d.current_due_date IS DISTINCT FROM (p_data->>'expected_due')::date OR d.updated_at IS DISTINCT FROM (p_data->>'expected_updated_at')::timestamptz THEN RAISE EXCEPTION 'CASE102_STALE'; END IF;
   END IF;
   did:=nullif(p_data->>'existing_id','')::uuid;
   IF did IS NOT NULL THEN
    IF p_data->>'kind'<>'answer' THEN RAISE EXCEPTION 'CASE102_INVALID_INPUT'; END IF;
    SELECT * INTO d FROM public.case_deadlines WHERE id=did AND case_id=p_case_id AND deadline_type='answer' AND status='Active' AND deleted_at IS NULL FOR UPDATE;
    IF d.id IS NULL THEN RAISE EXCEPTION 'CASE102_DEADLINE_UNAVAILABLE'; END IF;
    IF d.current_due_date IS DISTINCT FROM (p_data->>'expected_due')::date OR d.updated_at IS DISTINCT FROM (p_data->>'expected_updated_at')::timestamptz THEN RAISE EXCEPTION 'CASE102_STALE'; END IF;
   ELSE
    due:=(p_data->>'due')::date;
    IF due IS NULL OR NOT isfinite(due) THEN RAISE EXCEPTION 'CASE102_INVALID_INPUT'; END IF;
    IF p_data->>'kind'='court' AND why IS NULL THEN RAISE EXCEPTION 'CASE102_REASON_REQUIRED'; END IF;
    INSERT INTO public.case_deadlines(case_id,order_no,deadline_type,deadline_other,original_due_date,current_due_date,status,note)
    VALUES(p_case_id,(SELECT coalesce(max(order_no),0)+1 FROM public.case_deadlines WHERE case_id=p_case_id),CASE WHEN p_data->>'kind'='answer' THEN 'answer' ELSE 'other' END,
     CASE WHEN p_data->>'kind'='default' THEN 'คำร้องขาดนัด' WHEN p_data->>'kind'='court' THEN why END,due,due,'Active',why) RETURNING * INTO d;
    did:=d.id;deadline_after:=to_jsonb(d);
   END IF;
   IF p_data->>'kind'='answer' THEN UPDATE public.case_service_controls SET answer_deadline_id=did WHERE party_id=p_party_id;
   ELSIF p_data->>'kind'='default' THEN UPDATE public.case_service_controls SET default_deadline_id=did WHERE party_id=p_party_id; END IF;
  ELSIF p_action='answer' THEN
   event_day:=(p_data->>'date')::date;
   IF event_day IS NULL OR NOT isfinite(event_day) OR event_day>today OR c.answer_filed_on IS NOT NULL THEN RAISE EXCEPTION 'CASE102_INVALID_INPUT'; END IF;
   IF c.answer_deadline_id IS NOT NULL THEN
    SELECT * INTO d FROM public.case_deadlines WHERE id=c.answer_deadline_id AND case_id=p_case_id AND deleted_at IS NULL AND status='Active' FOR UPDATE;
    IF d.id IS NULL THEN RAISE EXCEPTION 'CASE102_DEADLINE_UNAVAILABLE'; END IF;
    IF d.current_due_date IS DISTINCT FROM (p_data->>'expected_due')::date OR d.updated_at IS DISTINCT FROM (p_data->>'expected_updated_at')::timestamptz THEN RAISE EXCEPTION 'CASE102_STALE'; END IF;
    deadline_before:=to_jsonb(d);
    UPDATE public.case_deadlines SET status='Done',updated_at=clock_timestamp() WHERE id=d.id RETURNING to_jsonb(case_deadlines.*) INTO deadline_after;
   END IF;
   UPDATE public.case_service_controls SET answer_filed_on=event_day WHERE party_id=p_party_id;
  ELSIF p_action='absence' THEN
   IF p_data->'confirmed' IS DISTINCT FROM 'true'::jsonb THEN RAISE EXCEPTION 'CASE102_CONFIRM_REQUIRED'; END IF;
   target:=(p_data->>'hearing_id')::uuid;
   PERFORM 1 FROM public.case_timeline WHERE id=target AND case_id=p_case_id AND event_type='hearing' AND deleted_at IS NULL AND status IS DISTINCT FROM 'Cancelled'
    AND CASE WHEN event_date~'^\d{4}-\d{2}-\d{2}$' THEN event_date::date BETWEEN (SELECT attempted_on FROM public.case_service_attempts WHERE id=c.lawful_attempt_id) AND today ELSE false END FOR SHARE;
   IF NOT FOUND OR c.lawful_attempt_id IS NULL THEN RAISE EXCEPTION 'CASE102_BRANCH_EVIDENCE_REQUIRED'; END IF;
   UPDATE public.case_service_controls SET absent_hearing_id=target WHERE party_id=p_party_id;
  ELSIF p_action='next' THEN
   IF jsonb_typeof(p_data->'next') IS DISTINCT FROM 'object' THEN RAISE EXCEPTION 'CASE102_INVALID_INPUT'; END IF;
   person:=nullif(p_data->'next'->>'assignee_id','')::uuid;
   IF person IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.user_profiles WHERE id=person AND active AND account_type='operational' AND assignable AND NOT must_change_password AND role IN('admin','partner','lawyer','assistant_lawyer','staff')) THEN RAISE EXCEPTION 'CASE102_PERSON_INELIGIBLE'; END IF;
   next_before:=public.case098_read(p_case_id);
   next_after:=public.case098_save(p_case_id,(p_data->>'core_version')::integer,'next',p_data->'next');
  END IF;
  UPDATE public.case_service_controls SET version=p_version+1,updated_at=clock_timestamp(),updated_by=auth.uid() WHERE party_id=p_party_id RETURNING * INTO c;
  new_facts:=jsonb_build_object('control',to_jsonb(c),'attempts',(SELECT coalesce(jsonb_agg(to_jsonb(x) ORDER BY id),'[]') FROM public.case_service_attempts x WHERE party_id=p_party_id),'deadline',deadline_after,'next',next_after);
 END IF;
 INSERT INTO public.case_service_events(case_id,party_id,action,actor_id,before_data,after_data,request_id,request_data)
 VALUES(p_case_id,p_party_id,p_action,auth.uid(),old_facts||jsonb_build_object('deadline',deadline_before,'next',next_before),new_facts,p_request_id,req);
 INSERT INTO public.case_audit_logs(case_id,table_name,record_id,action,user_id,user_name,user_role,old_data,new_data,note)
 VALUES(p_case_id,'case_service_controls',coalesce(p_party_id,f.id)::text,'update',auth.uid(),coalesce(nullif(actor.staff_name,''),actor.full_name),actor.role,old_facts,new_facts,'case102_'||p_action);
 IF deadline_after IS NOT NULL THEN
  INSERT INTO public.case_audit_logs(case_id,table_name,record_id,action,user_id,user_name,user_role,old_data,new_data,note)
  VALUES(p_case_id,'case_deadlines',deadline_after->>'id',CASE WHEN deadline_before IS NULL THEN 'create' ELSE 'update' END,auth.uid(),coalesce(nullif(actor.staff_name,''),actor.full_name),actor.role,deadline_before,deadline_after,'case102_'||p_action);
 END IF;
 RETURN public.case102_read(p_case_id);
EXCEPTION WHEN invalid_text_representation OR invalid_datetime_format OR datetime_field_overflow OR check_violation OR not_null_violation OR foreign_key_violation OR unique_violation THEN RAISE EXCEPTION 'CASE102_INVALID_INPUT';
END $function$

case100_save(bigint,text,uuid,integer,uu.definition:
CREATE OR REPLACE FUNCTION public.case100_save(p_case_id bigint, p_section text, p_id uuid, p_version integer, p_request_id uuid, p_current_decision uuid, p_data jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE d public.case_continuation_decisions; current_d public.case_continuation_decisions;
 r public.case_rescue_requests; review public.case_close_reviews; actor public.user_profiles;
 old_facts jsonb; new_facts jsonb; table_name text; person uuid; facts jsonb; confirmed date; closed date; occurred timestamptz;
 request jsonb:=jsonb_build_object('case_id',p_case_id,'section',p_section,'version',p_version,'current_decision',p_current_decision,'data',p_data);
BEGIN
 IF NOT(public.case097_session_ready() AND public.can_view_case_data() AND public.case097_process_writer()) THEN RAISE EXCEPTION 'CASE100_FORBIDDEN' USING ERRCODE='42501'; END IF;
 IF p_id IS NULL OR p_request_id IS NULL OR p_section IS NULL OR p_section NOT IN('decision','rescue','review') OR p_version IS NULL OR p_version<0 OR jsonb_typeof(p_data) IS DISTINCT FROM 'object' THEN RAISE EXCEPTION 'CASE100_INVALID_INPUT'; END IF;
 PERFORM 1 FROM public.cases WHERE id=p_case_id FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'CASE100_NOT_FOUND'; END IF;
 SELECT * INTO actor FROM public.user_profiles WHERE id=auth.uid();
 SELECT * INTO current_d FROM public.case_continuation_decisions WHERE case_id=p_case_id ORDER BY sequence_no DESC LIMIT 1;
 IF p_section='decision' THEN
  SELECT * INTO d FROM public.case_continuation_decisions WHERE id=p_id;
  IF d.id IS NOT NULL THEN
   IF d.case_id<>p_case_id THEN RAISE EXCEPTION 'CASE100_NOT_FOUND'; END IF;
   IF d.request_id=p_request_id AND d.request_data=request AND d.recorded_by=auth.uid() THEN RETURN public.case100_read(p_case_id); END IF;
   RAISE EXCEPTION 'CASE100_DECISION_APPEND_ONLY';
  END IF;
  IF p_version<>0 OR current_d.id IS DISTINCT FROM p_current_decision THEN RAISE EXCEPTION 'CASE100_STALE'; END IF;
  IF EXISTS(SELECT 1 FROM jsonb_object_keys(p_data) k WHERE k NOT IN('decision','confirmed_on','note')) THEN RAISE EXCEPTION 'CASE100_INVALID_INPUT'; END IF;
  confirmed:=nullif(p_data->>'confirmed_on','')::date;
  IF confirmed>(now() AT TIME ZONE 'Asia/Bangkok')::date THEN RAISE EXCEPTION 'CASE100_INVALID_DATE'; END IF;
  INSERT INTO public.case_continuation_decisions(id,case_id,sequence_no,decision,confirmed_on,note,request_id,request_data,recorded_by)
   VALUES(p_id,p_case_id,coalesce(current_d.sequence_no,0)+1,p_data->>'decision',confirmed,nullif(btrim(p_data->>'note'),''),p_request_id,request,auth.uid()) RETURNING * INTO d;
  table_name:='case_continuation_decisions'; new_facts:=to_jsonb(d)-'request_id'-'request_data';
 ELSIF p_section='rescue' THEN
  SELECT * INTO r FROM public.case_rescue_requests WHERE id=p_id FOR UPDATE;
  IF r.id IS NOT NULL THEN
   IF r.case_id<>p_case_id THEN RAISE EXCEPTION 'CASE100_NOT_FOUND'; END IF;
   IF r.last_request_id=p_request_id THEN
    IF r.last_request IS DISTINCT FROM request OR r.updated_by<>auth.uid() THEN RAISE EXCEPTION 'CASE100_REQUEST_CONFLICT'; END IF;
    RETURN public.case100_read(p_case_id);
   END IF;
  END IF;
  IF coalesce(r.version,0)<>p_version THEN RAISE EXCEPTION 'CASE100_STALE'; END IF;
  IF EXISTS(SELECT 1 FROM jsonb_object_keys(p_data) k WHERE k NOT IN('escalated_to','subject','reason','occurred_at','status','resolution')) THEN RAISE EXCEPTION 'CASE100_INVALID_INPUT'; END IF;
  person:=(p_data->>'escalated_to')::uuid; occurred:=(p_data->>'occurred_at')::timestamptz;
  IF person IS NULL THEN RAISE EXCEPTION 'CASE100_PERSON_INELIGIBLE'; END IF;
  IF r.id IS NULL OR person IS DISTINCT FROM r.escalated_to THEN
   PERFORM 1 FROM public.user_profiles WHERE id=person AND active IS TRUE AND account_type='operational' AND assignable IS TRUE AND must_change_password IS FALSE AND role IN('admin','partner','lawyer','assistant_lawyer','staff') FOR SHARE;
   IF NOT FOUND THEN RAISE EXCEPTION 'CASE100_PERSON_INELIGIBLE'; END IF;
  END IF;
  IF occurred>clock_timestamp() THEN RAISE EXCEPTION 'CASE100_INVALID_DATE'; END IF;
  old_facts:=CASE WHEN r.id IS NULL THEN NULL ELSE to_jsonb(r)-'last_request_id'-'last_request' END;
  IF r.id IS NULL THEN
   INSERT INTO public.case_rescue_requests(id,case_id,requested_by,escalated_to,subject,reason,occurred_at,status,resolution,resolved_at,resolved_by,last_request_id,last_request,updated_by)
   VALUES(p_id,p_case_id,auth.uid(),person,btrim(p_data->>'subject'),btrim(p_data->>'reason'),occurred,p_data->>'status',nullif(btrim(p_data->>'resolution'),''),CASE WHEN p_data->>'status'='resolved' THEN clock_timestamp() END,CASE WHEN p_data->>'status'='resolved' THEN auth.uid() END,p_request_id,request,auth.uid()) RETURNING * INTO r;
  ELSE
   UPDATE public.case_rescue_requests SET escalated_to=person,subject=btrim(p_data->>'subject'),reason=btrim(p_data->>'reason'),occurred_at=occurred,status=p_data->>'status',resolution=nullif(btrim(p_data->>'resolution'),''),
    resolved_at=CASE WHEN p_data->>'status'='resolved' THEN coalesce(r.resolved_at,clock_timestamp()) END,resolved_by=CASE WHEN p_data->>'status'='resolved' THEN coalesce(r.resolved_by,auth.uid()) END,
    version=p_version+1,last_request_id=p_request_id,last_request=request,updated_by=auth.uid(),updated_at=clock_timestamp() WHERE id=p_id RETURNING * INTO r;
  END IF;
  table_name:='case_rescue_requests'; new_facts:=to_jsonb(r)-'last_request_id'-'last_request';
 ELSE
  SELECT * INTO review FROM public.case_close_reviews WHERE id=p_id FOR UPDATE;
  IF review.id IS NOT NULL THEN
   IF review.case_id<>p_case_id THEN RAISE EXCEPTION 'CASE100_NOT_FOUND'; END IF;
   IF review.last_request_id=p_request_id THEN
    IF review.last_request IS DISTINCT FROM request OR review.updated_by<>auth.uid() THEN RAISE EXCEPTION 'CASE100_REQUEST_CONFLICT'; END IF;
    RETURN public.case100_read(p_case_id);
   END IF;
  END IF;
  IF coalesce(review.version,0)<>p_version THEN RAISE EXCEPTION 'CASE100_STALE'; END IF;
  IF current_d.id IS DISTINCT FROM p_current_decision THEN RAISE EXCEPTION 'CASE100_STALE'; END IF;
  IF current_d.decision IS DISTINCT FROM 'end' OR (review.id IS NOT NULL AND review.decision_id<>current_d.id) THEN RAISE EXCEPTION 'CASE100_END_REQUIRED'; END IF;
  IF EXISTS(SELECT 1 FROM jsonb_object_keys(p_data) k WHERE k NOT IN('objective','variance','lessons','knowledge','document_ref','closed_at')) THEN RAISE EXCEPTION 'CASE100_INVALID_INPUT'; END IF;
  closed:=(p_data->>'closed_at')::date;
  IF closed>(now() AT TIME ZONE 'Asia/Bangkok')::date THEN RAISE EXCEPTION 'CASE100_INVALID_DATE'; END IF;
  old_facts:=CASE WHEN review.id IS NULL THEN NULL ELSE to_jsonb(review)-'last_request_id'-'last_request' END;
  IF review.id IS NULL THEN
   SELECT coalesce(jsonb_agg(jsonb_build_object('person_id',t.person_id,'team_role',t.team_role,'name',coalesce(nullif(p.staff_name,''),p.full_name)) ORDER BY t.team_role,t.person_id),'[]') INTO facts FROM public.case_team_assignments t JOIN public.user_profiles p ON p.id=t.person_id WHERE t.case_id=p_case_id;
   INSERT INTO public.case_close_reviews(id,case_id,decision_id,objective,variance,lessons,knowledge,document_ref,closed_at,team_evidence,recorded_by,updated_by,last_request_id,last_request)
   VALUES(p_id,p_case_id,current_d.id,p_data->>'objective',nullif(btrim(p_data->>'variance'),''),nullif(btrim(p_data->>'lessons'),''),nullif(btrim(p_data->>'knowledge'),''),nullif(btrim(p_data->>'document_ref'),''),closed,facts,auth.uid(),auth.uid(),p_request_id,request) RETURNING * INTO review;
  ELSE
   UPDATE public.case_close_reviews SET objective=p_data->>'objective',variance=nullif(btrim(p_data->>'variance'),''),lessons=nullif(btrim(p_data->>'lessons'),''),knowledge=nullif(btrim(p_data->>'knowledge'),''),document_ref=nullif(btrim(p_data->>'document_ref'),''),closed_at=closed,updated_by=auth.uid(),updated_at=clock_timestamp(),version=p_version+1,last_request_id=p_request_id,last_request=request WHERE id=p_id RETURNING * INTO review;
  END IF;
  table_name:='case_close_reviews'; new_facts:=to_jsonb(review)-'last_request_id'-'last_request';
 END IF;
 INSERT INTO public.case_audit_logs(case_id,table_name,record_id,action,user_id,user_name,user_role,old_data,new_data,note)
 VALUES(p_case_id,table_name,p_id::text,CASE WHEN old_facts IS NULL THEN 'create' ELSE 'update' END,auth.uid(),coalesce(nullif(actor.staff_name,''),actor.full_name),actor.role,old_facts,new_facts,'case100_'||p_section);
 RETURN public.case100_read(p_case_id);
EXCEPTION WHEN invalid_text_representation OR invalid_datetime_format OR datetime_field_overflow OR check_violation OR unique_violation OR not_null_violation OR foreign_key_violation THEN RAISE EXCEPTION 'CASE100_INVALID_INPUT';
END $function$
